INSERT INTO "questions" VALUES(159,8,'BG1.8',1,8,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "bhīṣhmaḥ"?','bhīṣhmaḥ','["yourself", "and", "Bheeshma", "Karna"]','"Bheeshma"','"bhīṣhmaḥ" means "Bheeshma", a crucial term in verse BG1.8.','Recall the verse breakdown.',10);
