INSERT INTO "questions" VALUES(302,19,'BG1.19',1,19,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "ghoṣhaḥ"?','ghoṣhaḥ','["sound", "of Dhritarashtra’s sons", "hearts", "that"]','"sound"','"ghoṣhaḥ" means "sound", a crucial term in verse BG1.19.','Recall the verse breakdown.',10);
