INSERT INTO "questions" VALUES(758,54,'BG2.7',2,7,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "Thee"?',NULL,'["धर्मसंमूढचेताः", "पृच्छामि", "कार्पण्यदोषोपहतस्वभावः", "त्वाम्"]','"त्वाम्"','The term "त्वाम्" corresponds directly to "Thee".','Check the word roots.',10);
