INSERT INTO "questions" VALUES(800,57,'BG2.10',2,10,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG2.10?',NULL,'["Arjuna", "Sanjaya", "Bhagavan Sri Krishna", "Narrator / Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(801,57,'BG2.10',2,10,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG2.10?',NULL,'["2.10 To him who was despondent in the midst of the two armies, Krishna, as if smiling, O Bharata, spoke these words.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"2.10 To him who was despondent in the midst of the two armies, Krishna, as if smiling, O Bharata, spoke these words."','Accurate translation: "2.10 To him who was despondent in the midst of the two armies, Krishna, as if smiling, O Bharata, spoke these words.".','Identify the key actors and actions described in the Sanskrit words.',15);
