INSERT INTO "questions" VALUES(813,58,'BG2.11',2,11,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG2.11?',NULL,'["Bhagavan Sri Krishna", "King Dhritarashtra", "Sanjaya", "Arjuna"]','"Bhagavan Sri Krishna"','This verse is spoken by Bhagavan Sri Krishna. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(814,58,'BG2.11',2,11,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG2.11?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "2.11 The Blessed Lord said  Thou hast grieved for those that should not be grieved for, yet thou speakest words of wisdom. The wise grieve neither for the living nor for the dead.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"2.11 The Blessed Lord said  Thou hast grieved for those that should not be grieved for, yet thou speakest words of wisdom. The wise grieve neither for the living nor for the dead."','Accurate translation: "2.11 The Blessed Lord said  Thou hast grieved for those that should not be grieved for, yet thou speakest words of wisdom. The wise grieve neither for the living nor for the dead.".','Identify the key actors and actions described in the Sanskrit words.',15);
