INSERT INTO "questions" VALUES(1148,84,'BG2.37',2,37,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "वा"?','वा','["(thou) wilt obtain", "or", "slain", "heaven"]','"or"','"वा" means "or", a crucial term in verse BG2.37.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(1149,84,'BG2.37',2,37,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "(thou) wilt obtain"?',NULL,'["प्राप्स्यसि", "वा", "स्वर्गम्", "हतः"]','"प्राप्स्यसि"','The term "प्राप्स्यसि" corresponds directly to "(thou) wilt obtain".','Check the word roots.',10);
