INSERT INTO "questions" VALUES(1243,91,'BG2.44',2,44,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG2.44?',NULL,'["Arjuna", "Bhagavan Sri Krishna", "Sanjaya", "Narrator / Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(1244,91,'BG2.44',2,44,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG2.44?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "2.44 For those who are attached to pleasure and power, whose minds are drawn away by such teaching, ï1thatï1 determinate reason is not formed which is steadily bent on meditation and Samadhi (superconscious state).", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"2.44 For those who are attached to pleasure and power, whose minds are drawn away by such teaching, ï1thatï1 determinate reason is not formed which is steadily bent on meditation and Samadhi (superconscious state)."','Accurate translation: "2.44 For those who are attached to pleasure and power, whose minds are drawn away by such teaching, ï1thatï1 determinate reason is not formed which is steadily bent on meditation and Samadhi (superconscious state).".','Identify the key actors and actions described in the Sanskrit words.',15);
