INSERT INTO "questions" VALUES(1369,101,'BG2.54',2,54,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "का"?','का','["of the (sage of) steady wisdom", "what", "description", "of the (man) merged in the superconscious state"]','"what"','"का" means "what", a crucial term in verse BG2.54.','Recall the verse breakdown.',10);
