INSERT INTO "questions" VALUES(1408,104,'BG2.57',2,57,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "सर्वत्र"?','सर्वत्र','["he who", "without attachment", "everywhere", "that"]','"everywhere"','"सर्वत्र" means "everywhere", a crucial term in verse BG2.57.','Recall the verse breakdown.',10);
