INSERT INTO "questions" VALUES(1447,107,'BG2.60',2,60,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "हि"?','हि','["O Kaunteya (son of Kunti)", "indeed", "even", "of the striving"]','"indeed"','"हि" means "indeed", a crucial term in verse BG2.60.','Recall the verse breakdown.',10);
