INSERT INTO "questions" VALUES(1460,108,'BG2.61',2,61,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "सर्वाणि"?','सर्वाणि','["all", "joined", "them", "having restrained"]','"all"','"सर्वाणि" means "all", a crucial term in verse BG2.61.','Recall the verse breakdown.',10);
