INSERT INTO "questions" VALUES(1503,111,'BG2.64',2,64,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG2.64?',NULL,'["Sanjaya", "Bhagavan Sri Krishna", "Arjuna", "Narrator / Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(1504,111,'BG2.64',2,64,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG2.64?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "2.64 But the self-controlled man, moving among the objects with the senses under restraint and free from attraction and repulsion, attains to peace.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"2.64 But the self-controlled man, moving among the objects with the senses under restraint and free from attraction and repulsion, attains to peace."','Accurate translation: "2.64 But the self-controlled man, moving among the objects with the senses under restraint and free from attraction and repulsion, attains to peace.".','Identify the key actors and actions described in the Sanskrit words.',15);
