INSERT INTO "questions" VALUES(1550,115,'BG2.68',2,68,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "तस्मात्" mean in this verse?','तस्मात्','["O mightyarmed", "restrained", "whose", "therefore"]','"therefore"','"तस्मात्" translates directly to "therefore" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(1551,115,'BG2.68',2,68,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "यस्य"?','यस्य','["therefore", "whose", "restrained", "O mightyarmed"]','"whose"','"यस्य" means "whose", a crucial term in verse BG2.68.','Recall the verse breakdown.',10);
