INSERT INTO "questions" VALUES(1628,121,'BG3.2',3,2,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "इव"?','इव','["perplexing", "understanding", "with speech", "as it were"]','"as it were"','"इव" means "as it were", a crucial term in verse BG3.2.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(1629,121,'BG3.2',3,2,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "with speech"?',NULL,'["इव", "वाक्येन", "व्यामिश्रेण", "बुद्धिम्"]','"वाक्येन"','The term "वाक्येन" corresponds directly to "with speech".','Check the word roots.',10);
