INSERT INTO "questions" VALUES(1659,123,'BG3.4',3,4,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG3.4?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "3.4 Not by non-performance of actions does man reach actionlessness; nor by mere renunciation does he attain to perfection."]','"3.4 Not by non-performance of actions does man reach actionlessness; nor by mere renunciation does he attain to perfection."','Accurate translation: "3.4 Not by non-performance of actions does man reach actionlessness; nor by mere renunciation does he attain to perfection.".','Identify the key actors and actions described in the Sanskrit words.',15);
