INSERT INTO "questions" VALUES(1749,130,'BG3.11',3,11,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG3.11?',NULL,'["Bhagavan Sri Krishna", "Sanjaya", "Arjuna", "Narrator / Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(1750,130,'BG3.11',3,11,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG3.11?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "3.11 With this do ye nourish the gods and may those gods nourish you; thus nourishing one another, ye shall attain to the highest good.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"3.11 With this do ye nourish the gods and may those gods nourish you; thus nourishing one another, ye shall attain to the highest good."','Accurate translation: "3.11 With this do ye nourish the gods and may those gods nourish you; thus nourishing one another, ye shall attain to the highest good.".','Identify the key actors and actions described in the Sanskrit words.',15);
