INSERT INTO "questions" VALUES(1888,141,'BG3.22',3,22,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "मे"?','मे','["is", "not", "my", "O Partha"]','"my"','"मे" means "my", a crucial term in verse BG3.22.','Recall the verse breakdown.',10);
