INSERT INTO "questions" VALUES(1914,143,'BG3.24',3,24,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "इमे"?','इमे','["worlds", "would perish", "these", "not"]','"these"','"इमे" means "these", a crucial term in verse BG3.24.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(1915,143,'BG3.24',3,24,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "worlds"?',NULL,'["न", "उत्सीदेयुः", "लोकाः", "इमे"]','"लोकाः"','The term "लोकाः" corresponds directly to "worlds".','Check the word roots.',10);
