INSERT INTO "questions" VALUES(2005,150,'BG3.31',3,31,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "मे"?','मे','["My", "this", "those who", "teaching"]','"My"','"मे" means "My", a crucial term in verse BG3.31.','Recall the verse breakdown.',10);
