INSERT INTO "questions" VALUES(2270,170,'BG4.8',4,8,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG4.8?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "4.8 For the protection of the good, for the destruction of the wicked and for the establishment of righteousness, I am born in every age.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"4.8 For the protection of the good, for the destruction of the wicked and for the establishment of righteousness, I am born in every age."','Accurate translation: "4.8 For the protection of the good, for the destruction of the wicked and for the establishment of righteousness, I am born in every age.".','Identify the key actors and actions described in the Sanskrit words.',15);
