INSERT INTO "questions" VALUES(2361,177,'BG4.15',4,15,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG4.15?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "4.15 Having known this, the ancient seekers after freedom also performed action; therefore do thou also perform action, as did the ancients in days of yore."]','"4.15 Having known this, the ancient seekers after freedom also performed action; therefore do thou also perform action, as did the ancients in days of yore."','Accurate translation: "4.15 Having known this, the ancient seekers after freedom also performed action; therefore do thou also perform action, as did the ancients in days of yore.".','Identify the key actors and actions described in the Sanskrit words.',15);
