INSERT INTO "questions" VALUES(2448,184,'BG4.22',4,22,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "free from envy"?',NULL,'["विमत्सरः", "समः", "यदृच्छालाभसन्तुष्टः", "द्वन्द्वातीतः"]','"विमत्सरः"','The term "विमत्सरः" corresponds directly to "free from envy".','Check the word roots.',10);
