INSERT INTO "questions" VALUES(2616,197,'BG4.35',4,35,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "ज्ञात्वा"?','ज्ञात्वा','["not", "which", "again", "having known"]','"having known"','"ज्ञात्वा" means "having known", a crucial term in verse BG4.35.','Recall the verse breakdown.',10);
