INSERT INTO "questions" VALUES(2660,200,'BG4.38',4,38,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG4.38?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "4.38 Verily, there is no purifier in this world like knowledge. He who is perfected in Yoga finds it in the Self in time."]','"4.38 Verily, there is no purifier in this world like knowledge. He who is perfected in Yoga finds it in the Self in time."','Accurate translation: "4.38 Verily, there is no purifier in this world like knowledge. He who is perfected in Yoga finds it in the Self in time.".','Identify the key actors and actions described in the Sanskrit words.',15);
