INSERT INTO "questions" VALUES(2737,206,'BG5.2',5,2,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG5.2?',NULL,'["Arjuna", "Bhagavan Sri Krishna", "King Dhritarashtra", "Sanjaya"]','"Bhagavan Sri Krishna"','This verse is spoken by Bhagavan Sri Krishna. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(2738,206,'BG5.2',5,2,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG5.2?',NULL,'["The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "5.2 The Blessed Lord said  Renunciation and the Yoga of action both lead to the highest bliss; but of the two, the Yoga of action is superior to the renunciation of action.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"5.2 The Blessed Lord said  Renunciation and the Yoga of action both lead to the highest bliss; but of the two, the Yoga of action is superior to the renunciation of action."','Accurate translation: "5.2 The Blessed Lord said  Renunciation and the Yoga of action both lead to the highest bliss; but of the two, the Yoga of action is superior to the renunciation of action.".','Identify the key actors and actions described in the Sanskrit words.',15);
