INSERT INTO "questions" VALUES(2790,210,'BG5.6',5,6,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG5.6?',NULL,'["5.6 But renunciation, O mighty-armed Arjuna, is hard to attain without Yoga; the Yoga-harmonised sage ickly goes to Brahman.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"5.6 But renunciation, O mighty-armed Arjuna, is hard to attain without Yoga; the Yoga-harmonised sage ickly goes to Brahman."','Accurate translation: "5.6 But renunciation, O mighty-armed Arjuna, is hard to attain without Yoga; the Yoga-harmonised sage ickly goes to Brahman.".','Identify the key actors and actions described in the Sanskrit words.',15);
