INSERT INTO "questions" VALUES(2840,214,'BG5.10',5,10,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG5.10?',NULL,'["Bhagavan Sri Krishna", "Arjuna", "Narrator / Sanjaya", "Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(2841,214,'BG5.10',5,10,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG5.10?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "5.10 He who does actions, offering them to Brahman, and abandoning attachment, is not tainted by sin, just as a lotus-leaf is not tainted by water.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"5.10 He who does actions, offering them to Brahman, and abandoning attachment, is not tainted by sin, just as a lotus-leaf is not tainted by water."','Accurate translation: "5.10 He who does actions, offering them to Brahman, and abandoning attachment, is not tainted by sin, just as a lotus-leaf is not tainted by water.".','Identify the key actors and actions described in the Sanskrit words.',15);
