INSERT INTO "questions" VALUES(3124,236,'BG6.3',6,3,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG6.3?',NULL,'["Bhagavan Sri Krishna", "Arjuna", "Sanjaya", "Narrator / Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(3125,236,'BG6.3',6,3,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG6.3?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "6.3 For a sage who wishes to attain to Yoga, action is said to be the means; for the same sage who has attained to Yoga, inaction (iescence) is said to be the means.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"6.3 For a sage who wishes to attain to Yoga, action is said to be the means; for the same sage who has attained to Yoga, inaction (iescence) is said to be the means."','Accurate translation: "6.3 For a sage who wishes to attain to Yoga, action is said to be the means; for the same sage who has attained to Yoga, inaction (iescence) is said to be the means.".','Identify the key actors and actions described in the Sanskrit words.',15);
