INSERT INTO "questions" VALUES(3198,242,'BG6.9',6,9,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "in"?','in','["friends", "the indifferent", "in the goodhearted", "enemies"]','"friends"','"in" means "friends", a crucial term in verse BG6.9.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(3199,242,'BG6.9',6,9,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "enemies"?',NULL,'["साधुषु", "सुह्यन्मित्रार्युदासीनमध्यस्थद्वेष्यबन्धुषु", "अपि", "in"]','"in"','The term "in" corresponds directly to "enemies".','Check the word roots.',10);
