INSERT INTO "questions" VALUES(3576,271,'BG6.38',6,38,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG6.38?',NULL,'["Swami Sivananda did not comment on this sloka", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"Swami Sivananda did not comment on this sloka"','Accurate translation: "Swami Sivananda did not comment on this sloka".','Identify the key actors and actions described in the Sanskrit words.',15);
