INSERT INTO "questions" VALUES(3718,282,'BG7.2',7,2,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG7.2?',NULL,'["7.2 I shall declare to thee in full this knowledge combined with realisation, after knowing which nothing more here remains to be known.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"7.2 I shall declare to thee in full this knowledge combined with realisation, after knowing which nothing more here remains to be known."','Accurate translation: "7.2 I shall declare to thee in full this knowledge combined with realisation, after knowing which nothing more here remains to be known.".','Identify the key actors and actions described in the Sanskrit words.',15);
