INSERT INTO "questions" VALUES(3861,293,'BG7.13',7,13,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG7.13?',NULL,'["The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "7.13 Deluded by these Natures (states or things) composed of the three alities of Nature all this world does not know Me as distinct from them and immutable.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"7.13 Deluded by these Natures (states or things) composed of the three alities of Nature all this world does not know Me as distinct from them and immutable."','Accurate translation: "7.13 Deluded by these Natures (states or things) composed of the three alities of Nature all this world does not know Me as distinct from them and immutable.".','Identify the key actors and actions described in the Sanskrit words.',15);
