INSERT INTO "questions" VALUES(3989,303,'BG7.23',7,23,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','अन्तवत्तु फलं तेषां तद्भवत्यल्पमेधसाम् |','["|", "तद्भवत्यल्पमेधसाम्", "अन्तवत्तु", "फलं", "तेषां"]','["अन्तवत्तु", "फलं", "तेषां", "तद्भवत्यल्पमेधसाम्", "|"]','Correct sequence: अन्तवत्तु फलं तेषां तद्भवत्यल्पमेधसाम् |. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
