INSERT INTO "questions" VALUES(4078,310,'BG7.30',7,30,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "with the Adhiyajna"?',NULL,'["साधिभूताधिदैवम्", "साधियज्ञम्", "च", "माम्"]','"साधियज्ञम्"','The term "साधियज्ञम्" corresponds directly to "with the Adhiyajna".','Check the word roots.',10);
