INSERT INTO "questions" VALUES(4233,322,'BG8.12',8,12,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG8.12?',NULL,'["The kings gathered to celebrate their victory and distribute royal riches among the priests.", "8.12 Having closed all the gates, confined the mind in the heart and fixed the life-breath in the head, engaged in the practice of concentration.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"8.12 Having closed all the gates, confined the mind in the heart and fixed the life-breath in the head, engaged in the practice of concentration."','Accurate translation: "8.12 Having closed all the gates, confined the mind in the heart and fixed the life-breath in the head, engaged in the practice of concentration.".','Identify the key actors and actions described in the Sanskrit words.',15);
