INSERT INTO "questions" VALUES(4281,326,'BG8.16',8,16,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "subject to return"?',NULL,'["लोकाः", "पुनरावर्तिनः", "आब्रह्मभुवनात्", "अर्जुन"]','"पुनरावर्तिनः"','The term "पुनरावर्तिनः" corresponds directly to "subject to return".','Check the word roots.',10);
