INSERT INTO "questions" VALUES(4454,339,'BG9.1',9,1,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG9.1?',NULL,'["King Dhritarashtra", "Bhagavan Sri Krishna", "Sanjaya", "Arjuna"]','"Bhagavan Sri Krishna"','This verse is spoken by Bhagavan Sri Krishna. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(4455,339,'BG9.1',9,1,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG9.1?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "9.1 The Blessed Lord said  I shall now declare to thee who does not cavil, the greatest secret, the knowledge combined with experience (Self-realisation). Having known this thou shalt be free evil."]','"9.1 The Blessed Lord said  I shall now declare to thee who does not cavil, the greatest secret, the knowledge combined with experience (Self-realisation). Having known this thou shalt be free evil."','Accurate translation: "9.1 The Blessed Lord said  I shall now declare to thee who does not cavil, the greatest secret, the knowledge combined with experience (Self-realisation). Having known this thou shalt be free evil.".','Identify the key actors and actions described in the Sanskrit words.',15);
