INSERT INTO "questions" VALUES(4675,356,'BG9.18',9,18,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG9.18?',NULL,'["Sanjaya", "Narrator / Sanjaya", "Bhagavan Sri Krishna", "Arjuna"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(4676,356,'BG9.18',9,18,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG9.18?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "9.18 I am the goal, the supporter, the Lord, the witness, the abode, the shelter, the friend, the origin, the dissolution, the foundation, the treasure-house and the seed which is imperishable.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"9.18 I am the goal, the supporter, the Lord, the witness, the abode, the shelter, the friend, the origin, the dissolution, the foundation, the treasure-house and the seed which is imperishable."','Accurate translation: "9.18 I am the goal, the supporter, the Lord, the witness, the abode, the shelter, the friend, the origin, the dissolution, the foundation, the treasure-house and the seed which is imperishable.".','Identify the key actors and actions described in the Sanskrit words.',15);
