INSERT INTO "questions" VALUES(4833,368,'BG9.30',9,30,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG9.30?',NULL,'["Arjuna", "Narrator / Sanjaya", "Sanjaya", "Bhagavan Sri Krishna"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(4834,368,'BG9.30',9,30,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG9.30?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "9.30 Even if the most sinful worships Me, with devotion to none else, he too should indeed by regarded as righteous for he has rightly resolved.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"9.30 Even if the most sinful worships Me, with devotion to none else, he too should indeed by regarded as righteous for he has rightly resolved."','Accurate translation: "9.30 Even if the most sinful worships Me, with devotion to none else, he too should indeed by regarded as righteous for he has rightly resolved.".','Identify the key actors and actions described in the Sanskrit words.',15);
