INSERT INTO "questions" VALUES(4881,372,'BG9.34',9,34,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "भव"?','भव','["sacrificing unto Me", "with mind filled with Me", "be thou", "My devotee"]','"be thou"','"भव" means "be thou", a crucial term in verse BG9.34.','Recall the verse breakdown.',10);
