INSERT INTO "questions" VALUES(5016,382,'BG10.10',10,10,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG10.10?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "10.10 To them who are ever steadfast, worshipping Me with love, I give the Yoga of discrimination by which they come to Me.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"10.10 To them who are ever steadfast, worshipping Me with love, I give the Yoga of discrimination by which they come to Me."','Accurate translation: "10.10 To them who are ever steadfast, worshipping Me with love, I give the Yoga of discrimination by which they come to Me.".','Identify the key actors and actions described in the Sanskrit words.',15);
