INSERT INTO "questions" VALUES(5048,385,'BG10.13',10,13,1,1,'match_pairs','beginner','Match the Sanskrit words to their English meanings','Connect each Sanskrit word from the verse with its correct meaning:',NULL,'{"words": ["आहुः", "त्वाम्", "ऋषयः", "सर्वे"], "meanings": ["Thee", "(they) declared", "all", "the Rishis"]}','{"आहुः": "(they) declared", "त्वाम्": "Thee", "ऋषयः": "the Rishis", "सर्वे": "all"}','In verse BG10.13, these core words establish the setting and emotional tension of the dialogue.','Focus on the root meanings used in classical Sanskrit.',15);
INSERT INTO "questions" VALUES(5049,385,'BG10.13',10,13,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "आहुः" mean in this verse?','आहुः','["the Rishis", "all", "(they) declared", "Thee"]','"(they) declared"','"आहुः" translates directly to "(they) declared" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(5050,385,'BG10.13',10,13,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "त्वाम्"?','त्वाम्','["Thee", "all", "(they) declared", "the Rishis"]','"Thee"','"त्वाम्" means "Thee", a crucial term in verse BG10.13.','Recall the verse breakdown.',10);
