INSERT INTO "questions" VALUES(5224,398,'BG10.26',10,26,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG10.26?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "10.26 Among all the trees ( I am) the Peepul; among the divine sages, I am Narada; among Gandharvas, Chitraratha; among the perfected, the sage Kapila.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"10.26 Among all the trees ( I am) the Peepul; among the divine sages, I am Narada; among Gandharvas, Chitraratha; among the perfected, the sage Kapila."','Accurate translation: "10.26 Among all the trees ( I am) the Peepul; among the divine sages, I am Narada; among Gandharvas, Chitraratha; among the perfected, the sage Kapila.".','Identify the key actors and actions described in the Sanskrit words.',15);
