INSERT INTO "questions" VALUES(5367,409,'BG10.37',10,37,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG10.37?',NULL,'["10.37 Among the Vrishnis I am Vaasudeva; among the Pandavas I am Arjuna; among the sages I am Vyasa; among the Poets I am Usanas, the poet.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"10.37 Among the Vrishnis I am Vaasudeva; among the Pandavas I am Arjuna; among the sages I am Vyasa; among the Poets I am Usanas, the poet."','Accurate translation: "10.37 Among the Vrishnis I am Vaasudeva; among the Pandavas I am Arjuna; among the sages I am Vyasa; among the Poets I am Usanas, the poet.".','Identify the key actors and actions described in the Sanskrit words.',15);
