INSERT INTO "questions" VALUES(5414,413,'BG10.41',10,41,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "विभूतिमत्"?','विभूतिमत्','["prosperous", "यत् whatever", "glorious", "being"]','"glorious"','"विभूतिमत्" means "glorious", a crucial term in verse BG10.41.','Recall the verse breakdown.',10);
