INSERT INTO "questions" VALUES(5647,431,'BG11.17',11,17,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "गदिनम्"?','गदिनम्','["with discus", "with club", "and", "one with diadem"]','"with club"','"गदिनम्" means "with club", a crucial term in verse BG11.17.','Recall the verse breakdown.',10);
