INSERT INTO "questions" VALUES(5768,440,'BG11.26',11,26,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "अमी" mean in this verse?','अमी','["of Dhritarashtra", "and", "these", "Thee"]','"these"','"अमी" translates directly to "these" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(5769,440,'BG11.26',11,26,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "च"?','च','["these", "Thee", "of Dhritarashtra", "and"]','"and"','"च" means "and", a crucial term in verse BG11.26.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(5770,440,'BG11.26',11,26,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "Thee"?',NULL,'["अमी", "त्वाम्", "धृतराष्ट्रस्य", "च"]','"त्वाम्"','The term "त्वाम्" corresponds directly to "Thee".','Check the word roots.',10);
