INSERT INTO "questions" VALUES(6016,458,'BG11.44',11,44,1,2,'mcq_vocab','beginner','Select the correct meaning','What does the Sanskrit word "तस्मात्" mean in this verse?','तस्मात्','["therefore", "saluting", "body", "having bent"]','"therefore"','"तस्मात्" translates directly to "therefore" in the context of this shloka.','Break down the compound word or root prefix.',10);
INSERT INTO "questions" VALUES(6017,458,'BG11.44',11,44,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "प्रणम्य"?','प्रणम्य','["saluting", "body", "therefore", "having bent"]','"saluting"','"प्रणम्य" means "saluting", a crucial term in verse BG11.44.','Recall the verse breakdown.',10);
INSERT INTO "questions" VALUES(6018,458,'BG11.44',11,44,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "having bent"?',NULL,'["कायम्", "प्रणिधाय", "तस्मात्", "प्रणम्य"]','"प्रणिधाय"','The term "प्रणिधाय" corresponds directly to "having bent".','Check the word roots.',10);
