INSERT INTO "questions" VALUES(6090,463,'BG11.49',11,49,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','मा ते व्यथा मा च विमूढभावो','["व्यथा", "च", "मा", "ते", "मा"]','["मा", "ते", "व्यथा", "मा", "च"]','Correct sequence: मा ते व्यथा मा च. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
