INSERT INTO "questions" VALUES(6130,466,'BG11.52',11,52,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG11.52?',NULL,'["Arjuna", "Sanjaya", "Bhagavan Sri Krishna", "King Dhritarashtra"]','"Bhagavan Sri Krishna"','This verse is spoken by Bhagavan Sri Krishna. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(6131,466,'BG11.52',11,52,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG11.52?',NULL,'["11.52 The Blessed Lord said  Very hard indeed it is to see this form of Mine which thou hast seen. Even the gods are ever longing to behold it.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"11.52 The Blessed Lord said  Very hard indeed it is to see this form of Mine which thou hast seen. Even the gods are ever longing to behold it."','Accurate translation: "11.52 The Blessed Lord said  Very hard indeed it is to see this form of Mine which thou hast seen. Even the gods are ever longing to behold it.".','Identify the key actors and actions described in the Sanskrit words.',15);
