INSERT INTO "questions" VALUES(6195,471,'BG12.2',12,2,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG12.2?',NULL,'["Arjuna", "King Dhritarashtra", "Bhagavan Sri Krishna", "Sanjaya"]','"Bhagavan Sri Krishna"','This verse is spoken by Bhagavan Sri Krishna. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(6196,471,'BG12.2',12,2,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG12.2?',NULL,'["12.2 The Blessed Lord said  Those who, fixing their mind on Me, worship Me, ever steadfast and endowed with supreme faith, are the best in Yoga in My opinion.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"12.2 The Blessed Lord said  Those who, fixing their mind on Me, worship Me, ever steadfast and endowed with supreme faith, are the best in Yoga in My opinion."','Accurate translation: "12.2 The Blessed Lord said  Those who, fixing their mind on Me, worship Me, ever steadfast and endowed with supreme faith, are the best in Yoga in My opinion.".','Identify the key actors and actions described in the Sanskrit words.',15);
