INSERT INTO "questions" VALUES(6230,474,'BG12.5',12,5,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG12.5?',NULL,'["Narrator / Sanjaya", "Bhagavan Sri Krishna", "Sanjaya", "Arjuna"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(6231,474,'BG12.5',12,5,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG12.5?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "12.5 Greater is their trouble whose minds are set on the unmanifested; for the goal; the unmanifested, is very hard for the embodied to reach.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"12.5 Greater is their trouble whose minds are set on the unmanifested; for the goal; the unmanifested, is very hard for the embodied to reach."','Accurate translation: "12.5 Greater is their trouble whose minds are set on the unmanifested; for the goal; the unmanifested, is very hard for the embodied to reach.".','Identify the key actors and actions described in the Sanskrit words.',15);
