INSERT INTO "questions" VALUES(6457,492,'BG13.3',13,3,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "च"?','च','["and", "also", "the knower of the field", "Me"]','"and"','"च" means "and", a crucial term in verse BG13.3.','Recall the verse breakdown.',10);
