INSERT INTO "questions" VALUES(6514,496,'BG13.7',13,7,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG13.7?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "13.7 Desire, hatred, pleasure, pain, the aggregate (the body), intelligence, fortitude  the field has thus been briefly described with its modifications.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"13.7 Desire, hatred, pleasure, pain, the aggregate (the body), intelligence, fortitude  the field has thus been briefly described with its modifications."','Accurate translation: "13.7 Desire, hatred, pleasure, pain, the aggregate (the body), intelligence, fortitude  the field has thus been briefly described with its modifications.".','Identify the key actors and actions described in the Sanskrit words.',15);
