INSERT INTO "questions" VALUES(6549,499,'BG13.10',13,10,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "in son"?',NULL,'["असक्तिः", "अनभिष्वङ्गः", "पुत्रदारगृहादिषु", "home"]','"पुत्रदारगृहादिषु"','The term "पुत्रदारगृहादिषु" corresponds directly to "in son".','Check the word roots.',10);
