INSERT INTO "questions" VALUES(6552,499,'BG13.10',13,10,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG13.10?',NULL,'["Narrator / Sanjaya", "Arjuna", "Sanjaya", "Bhagavan Sri Krishna"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(6553,499,'BG13.10',13,10,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG13.10?',NULL,'["The kings gathered to celebrate their victory and distribute royal riches among the priests.", "13.10 Non-attachment, non-identification of the Self with son, wife, home and the rest, and constant even-mindedness on the attainment of the desirable and the undesirable.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"13.10 Non-attachment, non-identification of the Self with son, wife, home and the rest, and constant even-mindedness on the attainment of the desirable and the undesirable."','Accurate translation: "13.10 Non-attachment, non-identification of the Self with son, wife, home and the rest, and constant even-mindedness on the attainment of the desirable and the undesirable.".','Identify the key actors and actions described in the Sanskrit words.',15);
