INSERT INTO "questions" VALUES(6566,500,'BG13.11',13,11,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG13.11?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "13.11 Unswerving devotion unto Me by the Yoga of non-separation, resort to solitary places, distaste for the society of men."]','"13.11 Unswerving devotion unto Me by the Yoga of non-separation, resort to solitary places, distaste for the society of men."','Accurate translation: "13.11 Unswerving devotion unto Me by the Yoga of non-separation, resort to solitary places, distaste for the society of men.".','Identify the key actors and actions described in the Sanskrit words.',15);
