INSERT INTO "questions" VALUES(6600,503,'BG13.14',13,14,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "पाणिपादम्"?','पाणिपादम्','["everywhere", "with hands and feet", "everywhere", "that"]','"with hands and feet"','"पाणिपादम्" means "with hands and feet", a crucial term in verse BG13.14.','Recall the verse breakdown.',10);
