INSERT INTO "questions" VALUES(6683,509,'BG13.20',13,20,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG13.20?',NULL,'["The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "13.20 Know thou that Nature (matter) and the Spirit are both beginningless; and know also that all modifications and alities are born of Nature.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"13.20 Know thou that Nature (matter) and the Spirit are both beginningless; and know also that all modifications and alities are born of Nature."','Accurate translation: "13.20 Know thou that Nature (matter) and the Spirit are both beginningless; and know also that all modifications and alities are born of Nature.".','Identify the key actors and actions described in the Sanskrit words.',15);
