INSERT INTO "questions" VALUES(6748,514,'BG13.25',13,25,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG13.25?',NULL,'["The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "13.25 Some by meditation behold the Self in the self by the self, others by the Yoga of knowledge, and still others by the Yoga of action."]','"13.25 Some by meditation behold the Self in the self by the self, others by the Yoga of knowledge, and still others by the Yoga of action."','Accurate translation: "13.25 Some by meditation behold the Self in the self by the self, others by the Yoga of knowledge, and still others by the Yoga of action.".','Identify the key actors and actions described in the Sanskrit words.',15);
