INSERT INTO "questions" VALUES(6825,520,'BG13.31',13,31,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG13.31?',NULL,'["Bhagavan Sri Krishna", "Sanjaya", "Arjuna", "Narrator / Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(6826,520,'BG13.31',13,31,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG13.31?',NULL,'["The kings gathered to celebrate their victory and distribute royal riches among the priests.", "13.31 When a man sees the whole variety of beings as resting in the One, and spreading forth from That alone, he then becomes Brahman.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"13.31 When a man sees the whole variety of beings as resting in the One, and spreading forth from That alone, he then becomes Brahman."','Accurate translation: "13.31 When a man sees the whole variety of beings as resting in the One, and spreading forth from That alone, he then becomes Brahman.".','Identify the key actors and actions described in the Sanskrit words.',15);
