INSERT INTO "questions" VALUES(6889,525,'BG14.1',14,1,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG14.1?',NULL,'["King Dhritarashtra", "Arjuna", "Sanjaya", "Bhagavan Sri Krishna"]','"Bhagavan Sri Krishna"','This verse is spoken by Bhagavan Sri Krishna. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(6890,525,'BG14.1',14,1,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG14.1?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "14.1 The Blessed Lord said  I will again declare (to thee) that supreme knowledge, the best of all knowledge, having known which all the sages have gone to the supreme perfection after this life.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"14.1 The Blessed Lord said  I will again declare (to thee) that supreme knowledge, the best of all knowledge, having known which all the sages have gone to the supreme perfection after this life."','Accurate translation: "14.1 The Blessed Lord said  I will again declare (to thee) that supreme knowledge, the best of all knowledge, having known which all the sages have gone to the supreme perfection after this life.".','Identify the key actors and actions described in the Sanskrit words.',15);
