INSERT INTO "questions" VALUES(7163,546,'BG14.22',14,22,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG14.22?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "14.22 The Blessed Lord said  When light, activity and delusion are present, he hates them not, nor does he long for them when they are absent.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"14.22 The Blessed Lord said  When light, activity and delusion are present, he hates them not, nor does he long for them when they are absent."','Accurate translation: "14.22 The Blessed Lord said  When light, activity and delusion are present, he hates them not, nor does he long for them when they are absent.".','Identify the key actors and actions described in the Sanskrit words.',15);
