INSERT INTO "questions" VALUES(7215,550,'BG14.26',14,26,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG14.26?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "14.26 And he who serves Me with unswerving devotion, he, crossing beyond the alities, is fit for becoming Brahman.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"14.26 And he who serves Me with unswerving devotion, he, crossing beyond the alities, is fit for becoming Brahman."','Accurate translation: "14.26 And he who serves Me with unswerving devotion, he, crossing beyond the alities, is fit for becoming Brahman.".','Identify the key actors and actions described in the Sanskrit words.',15);
