INSERT INTO "questions" VALUES(7277,555,'BG15.4',15,4,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "पदम्"?','पदम्','["That", "should be sought for", "goal", "then"]','"goal"','"पदम्" means "goal", a crucial term in verse BG15.4.','Recall the verse breakdown.',10);
