INSERT INTO "questions" VALUES(7330,559,'BG15.8',15,8,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "यत्"?','यत्','["when", "obtains", "a body", "and"]','"when"','"यत्" means "when", a crucial term in verse BG15.8.','Recall the verse breakdown.',10);
