INSERT INTO "questions" VALUES(7387,563,'BG15.12',15,12,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG15.12?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "15.12 That light which residing in the sun illumines the whole world, that which is in the moon and in the fire  know that light to be Mine."]','"15.12 That light which residing in the sun illumines the whole world, that which is in the moon and in the fire  know that light to be Mine."','Accurate translation: "15.12 That light which residing in the sun illumines the whole world, that which is in the moon and in the fire  know that light to be Mine.".','Identify the key actors and actions described in the Sanskrit words.',15);
