INSERT INTO "questions" VALUES(7531,574,'BG16.3',16,3,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG16.3?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "16.3 Vigour, forgiveness, fortitude, purity, absence of hatred, absence of pride  these belong to the one born for a divine state, O Arjuna.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"16.3 Vigour, forgiveness, fortitude, purity, absence of hatred, absence of pride  these belong to the one born for a divine state, O Arjuna."','Accurate translation: "16.3 Vigour, forgiveness, fortitude, purity, absence of hatred, absence of pride  these belong to the one born for a divine state, O Arjuna.".','Identify the key actors and actions described in the Sanskrit words.',15);
