INSERT INTO "questions" VALUES(7569,577,'BG16.6',16,6,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG16.6?',NULL,'["Narrator / Sanjaya", "Sanjaya", "Bhagavan Sri Krishna", "Arjuna"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(7570,577,'BG16.6',16,6,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG16.6?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "16.6 There are two types of beings in this world, the divine and the demoniacal; the divine has been described at length; hear from Me, O Arjuna, of the demoniacal."]','"16.6 There are two types of beings in this world, the divine and the demoniacal; the divine has been described at length; hear from Me, O Arjuna, of the demoniacal."','Accurate translation: "16.6 There are two types of beings in this world, the divine and the demoniacal; the divine has been described at length; hear from Me, O Arjuna, of the demoniacal.".','Identify the key actors and actions described in the Sanskrit words.',15);
