INSERT INTO "questions" VALUES(7605,580,'BG16.9',16,9,1,4,'mcq_reverse_vocab','intermediate','Identify the Sanskrit word','Which Sanskrit word from this verse means: "holding"?',NULL,'["दृष्टिम्", "नष्टात्मानः", "अवष्टभ्य", "एताम्"]','"अवष्टभ्य"','The term "अवष्टभ्य" corresponds directly to "holding".','Check the word roots.',10);
