INSERT INTO "questions" VALUES(7622,581,'BG16.10',16,10,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG16.10?',NULL,'["16.10 Filled with insatiable desires, full of hypocrisy, pride and arrogance, holding evil ideas through delusion, they work with impure resolves.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"16.10 Filled with insatiable desires, full of hypocrisy, pride and arrogance, holding evil ideas through delusion, they work with impure resolves."','Accurate translation: "16.10 Filled with insatiable desires, full of hypocrisy, pride and arrogance, holding evil ideas through delusion, they work with impure resolves.".','Identify the key actors and actions described in the Sanskrit words.',15);
