INSERT INTO "questions" VALUES(7712,588,'BG16.17',16,17,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG16.17?',NULL,'["Sanjaya", "Narrator / Sanjaya", "Arjuna", "Bhagavan Sri Krishna"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(7713,588,'BG16.17',16,17,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG16.17?',NULL,'["The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "16.17 Self-conceited, stubborn, filled with the pride and intoxication of wealth, they perform sacrifices in name out of ostentation, contrary to scriptural ordinances.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"16.17 Self-conceited, stubborn, filled with the pride and intoxication of wealth, they perform sacrifices in name out of ostentation, contrary to scriptural ordinances."','Accurate translation: "16.17 Self-conceited, stubborn, filled with the pride and intoxication of wealth, they perform sacrifices in name out of ostentation, contrary to scriptural ordinances.".','Identify the key actors and actions described in the Sanskrit words.',15);
