INSERT INTO "questions" VALUES(7890,602,'BG17.7',17,7,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "तु"?','तु','["indeed", "food", "of all", "also"]','"indeed"','"तु" means "indeed", a crucial term in verse BG17.7.','Recall the verse breakdown.',10);
