INSERT INTO "questions" VALUES(7893,602,'BG17.7',17,7,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','आहारस्त्वपि सर्वस्य त्रिविधो भवति प्रियः |','["भवति", "सर्वस्य", "आहारस्त्वपि", "त्रिविधो", "प्रियः"]','["आहारस्त्वपि", "सर्वस्य", "त्रिविधो", "भवति", "प्रियः"]','Correct sequence: आहारस्त्वपि सर्वस्य त्रिविधो भवति प्रियः. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
