INSERT INTO "questions" VALUES(7997,610,'BG17.15',17,15,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG17.15?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "17.15 Speech which causes no excitement, truthful, pleasant and beneficial, the practice of the study of the Vedas, are called austerity of speech.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"17.15 Speech which causes no excitement, truthful, pleasant and beneficial, the practice of the study of the Vedas, are called austerity of speech."','Accurate translation: "17.15 Speech which causes no excitement, truthful, pleasant and beneficial, the practice of the study of the Vedas, are called austerity of speech.".','Identify the key actors and actions described in the Sanskrit words.',15);
