INSERT INTO "questions" VALUES(8088,617,'BG17.22',17,22,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG17.22?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "17.22 The gift that is given at a wrong place and time, to unworthy persons, without respect or with insult is declared to be Tamasic.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins."]','"17.22 The gift that is given at a wrong place and time, to unworthy persons, without respect or with insult is declared to be Tamasic."','Accurate translation: "17.22 The gift that is given at a wrong place and time, to unworthy persons, without respect or with insult is declared to be Tamasic.".','Identify the key actors and actions described in the Sanskrit words.',15);
