INSERT INTO "questions" VALUES(8438,644,'BG18.21',18,21,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG18.21?',NULL,'["Arjuna", "Narrator / Sanjaya", "Bhagavan Sri Krishna", "Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(8439,644,'BG18.21',18,21,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG18.21?',NULL,'["18.21 But that knowledge which sees in all beings various entities of distinct kinds as different from one another  know thou that knowledge to be Rajasic.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"18.21 But that knowledge which sees in all beings various entities of distinct kinds as different from one another  know thou that knowledge to be Rajasic."','Accurate translation: "18.21 But that knowledge which sees in all beings various entities of distinct kinds as different from one another  know thou that knowledge to be Rajasic.".','Identify the key actors and actions described in the Sanskrit words.',15);
