INSERT INTO "questions" VALUES(8491,648,'BG18.25',18,25,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG18.25?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "18.25 That action which is undertaken from delusion, without a regard for the conseences, loss, injury and (one''s own) ability  that is declared to be Tamasic (dark)."]','"18.25 That action which is undertaken from delusion, without a regard for the conseences, loss, injury and (one''s own) ability  that is declared to be Tamasic (dark)."','Accurate translation: "18.25 That action which is undertaken from delusion, without a regard for the conseences, loss, injury and (one''s own) ability  that is declared to be Tamasic (dark).".','Identify the key actors and actions described in the Sanskrit words.',15);
