INSERT INTO "questions" VALUES(8503,649,'BG18.26',18,26,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG18.26?',NULL,'["Bhagavan Sri Krishna", "Sanjaya", "Narrator / Sanjaya", "Arjuna"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(8504,649,'BG18.26',18,26,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG18.26?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "18.26 An agent who is free from attachment, non-egoistic, endowed with firmness and enthusiasm, and unaffected by success or failure, is called Sattvic (pure).", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"18.26 An agent who is free from attachment, non-egoistic, endowed with firmness and enthusiasm, and unaffected by success or failure, is called Sattvic (pure)."','Accurate translation: "18.26 An agent who is free from attachment, non-egoistic, endowed with firmness and enthusiasm, and unaffected by success or failure, is called Sattvic (pure).".','Identify the key actors and actions described in the Sanskrit words.',15);
