INSERT INTO "questions" VALUES(8542,652,'BG18.29',18,29,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG18.29?',NULL,'["Bhagavan Sri Krishna", "Arjuna", "Sanjaya", "Narrator / Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(8543,652,'BG18.29',18,29,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG18.29?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "18.29 Hear thou the threefold division of intellect and firmness according to the Gunas, as I declare them fully and distinctly, O Arjuna.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests."]','"18.29 Hear thou the threefold division of intellect and firmness according to the Gunas, as I declare them fully and distinctly, O Arjuna."','Accurate translation: "18.29 Hear thou the threefold division of intellect and firmness according to the Gunas, as I declare them fully and distinctly, O Arjuna.".','Identify the key actors and actions described in the Sanskrit words.',15);
