INSERT INTO "questions" VALUES(8616,658,'BG18.35',18,35,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "स्वप्नम्"?','स्वप्नम्','["sleep", "fear", "grief", "by which"]','"sleep"','"स्वप्नम्" means "sleep", a crucial term in verse BG18.35.','Recall the verse breakdown.',10);
