INSERT INTO "questions" VALUES(8634,659,'BG18.36',18,36,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG18.36?',NULL,'["Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "18.36 And now hear from Me, O Arjuna, of the threefold pleasure, in which one rejoices by practice and surely comes to the end of pain."]','"18.36 And now hear from Me, O Arjuna, of the threefold pleasure, in which one rejoices by practice and surely comes to the end of pain."','Accurate translation: "18.36 And now hear from Me, O Arjuna, of the threefold pleasure, in which one rejoices by practice and surely comes to the end of pain.".','Identify the key actors and actions described in the Sanskrit words.',15);
