INSERT INTO "questions" VALUES(8722,666,'BG18.43',18,43,2,7,'word_order','advanced','Tap the words in the correct sequence to reconstruct the shloka','Reconstruct this line in its sacred order:','शौर्यं तेजो धृतिर्दाक्ष्यं युद्धे चाप्यपलायनम् |','["तेजो", "धृतिर्दाक्ष्यं", "चाप्यपलायनम्", "युद्धे", "शौर्यं"]','["शौर्यं", "तेजो", "धृतिर्दाक्ष्यं", "युद्धे", "चाप्यपलायनम्"]','Correct sequence: शौर्यं तेजो धृतिर्दाक्ष्यं युद्धे चाप्यपलायनम्. Word-order recitation strengthens memory and concentration.','Start with the first word of the chapter or verse.',20);
