INSERT INTO "questions" VALUES(8775,670,'BG18.47',18,47,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG18.47?',NULL,'["Sanjaya", "Bhagavan Sri Krishna", "Arjuna", "Narrator / Sanjaya"]','"Narrator / Sanjaya"','This verse is spoken by Narrator / Sanjaya. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(8776,670,'BG18.47',18,47,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG18.47?',NULL,'["The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle.", "18.47 Better is one''s own duty (though) destitute of merits, than the duty of another well performed. He who does the duty ordained by his own nature incurs no sin."]','"18.47 Better is one''s own duty (though) destitute of merits, than the duty of another well performed. He who does the duty ordained by his own nature incurs no sin."','Accurate translation: "18.47 Better is one''s own duty (though) destitute of merits, than the duty of another well performed. He who does the duty ordained by his own nature incurs no sin.".','Identify the key actors and actions described in the Sanskrit words.',15);
