INSERT INTO "questions" VALUES(8893,679,'BG18.56',18,56,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG18.56?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "18.56 Doing all actions always having taken refuge in Me, by My grace he obtains the eternal indestructible state of being.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"18.56 Doing all actions always having taken refuge in Me, by My grace he obtains the eternal indestructible state of being."','Accurate translation: "18.56 Doing all actions always having taken refuge in Me, by My grace he obtains the eternal indestructible state of being.".','Identify the key actors and actions described in the Sanskrit words.',15);
