INSERT INTO "questions" VALUES(8906,680,'BG18.57',18,57,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG18.57?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "18.57 Mentally renouncing all actions in Me, having Me as the highest goal, resorting to the Yoga of discrimination do thou ever fix thy mind on Me.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"18.57 Mentally renouncing all actions in Me, having Me as the highest goal, resorting to the Yoga of discrimination do thou ever fix thy mind on Me."','Accurate translation: "18.57 Mentally renouncing all actions in Me, having Me as the highest goal, resorting to the Yoga of discrimination do thou ever fix thy mind on Me.".','Identify the key actors and actions described in the Sanskrit words.',15);
