INSERT INTO "questions" VALUES(8957,684,'BG18.61',18,61,3,8,'speaker_context','beginner','Identify the speaker of this verse','Who is the speaker in verse BG18.61?',NULL,'["Sanjaya", "King Dhritarashtra", "Arjuna", "Bhagavan Sri Krishna"]','"Arjuna"','This verse is spoken by Arjuna. Understanding who is speaking reveals their mindset, doubts, and spiritual readiness.','Look at the introductory phrase (uvācha) preceding the shloka.',10);
INSERT INTO "questions" VALUES(8958,684,'BG18.61',18,61,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG18.61?',NULL,'["18.61 The Lord dwells in the hearts of all beings, O Arjuna, causing all beings, by His illusive power, to revolve as if mounted on a machine.", "Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"18.61 The Lord dwells in the hearts of all beings, O Arjuna, causing all beings, by His illusive power, to revolve as if mounted on a machine."','Accurate translation: "18.61 The Lord dwells in the hearts of all beings, O Arjuna, causing all beings, by His illusive power, to revolve as if mounted on a machine.".','Identify the key actors and actions described in the Sanskrit words.',15);
