INSERT INTO "questions" VALUES(9023,689,'BG18.66',18,66,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG18.66?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "18.66 Abandoning all duties, take refuge in Me alone: I will liberate thee from all sins; grieve not.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"18.66 Abandoning all duties, take refuge in Me alone: I will liberate thee from all sins; grieve not."','Accurate translation: "18.66 Abandoning all duties, take refuge in Me alone: I will liberate thee from all sins; grieve not.".','Identify the key actors and actions described in the Sanskrit words.',15);
