INSERT INTO "questions" VALUES(9031,690,'BG18.67',18,67,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "ते"?','ते','["by thee", "this", "to one who is devoid of austerity", "not"]','"by thee"','"ते" means "by thee", a crucial term in verse BG18.67.','Recall the verse breakdown.',10);
