INSERT INTO "questions" VALUES(9075,693,'BG18.70',18,70,3,9,'translation_mcq','intermediate','Select the most accurate translation of this shloka','Which translation accurately expresses verse BG18.70?',NULL,'["Sanjaya recounted the ancient lineages of the Kuru dynasty and their celestial origins.", "18.70 And he who will study this sacred dialogue of ours, by him I shall have been worshipped by the sacrifice of wisdom,  such is My conviction.", "The kings gathered to celebrate their victory and distribute royal riches among the priests.", "Arjuna laid down his bow and arrows, requesting Krishna to lead the armies away from battle."]','"18.70 And he who will study this sacred dialogue of ours, by him I shall have been worshipped by the sacrifice of wisdom,  such is My conviction."','Accurate translation: "18.70 And he who will study this sacred dialogue of ours, by him I shall have been worshipped by the sacrifice of wisdom,  such is My conviction.".','Identify the key actors and actions described in the Sanskrit words.',15);
