INSERT INTO "questions" VALUES(9174,701,'BG18.78',18,78,1,3,'mcq_vocab','beginner','Select the correct meaning','What is the meaning of "योगेश्वरः"?','योगेश्वरः','["wherever", "Krishna", "the Lord of Yoga", "wherever"]','"the Lord of Yoga"','"योगेश्वरः" means "the Lord of Yoga", a crucial term in verse BG18.78.','Recall the verse breakdown.',10);
