INSERT INTO "vocabulary" VALUES(1012,70,'BG2.23','मारुतः',NULL,'wind.Commentary The Self is indivisible. It has no parts. It is extremely subtle. It is infinite. Therefore');
INSERT INTO "vocabulary" VALUES(1013,70,'BG2.23','sword',NULL,'cannot cut It fire cannot burn It water cannot wet It wind cannot dry It');
