INSERT INTO "vocabulary" VALUES(1019,71,'BG2.24','अशोष्यः',NULL,'cannot be died');
INSERT INTO "vocabulary" VALUES(1020,71,'BG2.24','एव',NULL,'also');
INSERT INTO "vocabulary" VALUES(1021,71,'BG2.24','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(1022,71,'BG2.24','नित्यः',NULL,'eternal');
INSERT INTO "vocabulary" VALUES(1023,71,'BG2.24','सर्वगतः',NULL,'allpervading');
INSERT INTO "vocabulary" VALUES(1024,71,'BG2.24','स्थाणुः',NULL,'stable');
INSERT INTO "vocabulary" VALUES(1025,71,'BG2.24','अचलः',NULL,'immovable');
INSERT INTO "vocabulary" VALUES(1026,71,'BG2.24','अयम्',NULL,'this');
INSERT INTO "vocabulary" VALUES(1027,71,'BG2.24','सनातनः',NULL,'ancient.Commentary The Self is very subtle. It is beyond the reach of speech and mind. It is very difficult to understand this subtle Self. So Lord Krishna explains the nature of the immortal Self in a variety of ways with various illustrations and examples');
INSERT INTO "vocabulary" VALUES(1028,71,'BG2.24','so',NULL,'that It can be grasped by the people.Sword cannot cut this Self. It is eternal. Because It is eternal');
INSERT INTO "vocabulary" VALUES(1029,71,'BG2.24','It',NULL,'is allpervading. Because It is allpervading');
INSERT INTO "vocabulary" VALUES(1030,71,'BG2.24','It',NULL,'is stable like a stature. Because It is stable');
INSERT INTO "vocabulary" VALUES(1031,71,'BG2.24','It',NULL,'is immovable. It is everlasting. Therefore');
INSERT INTO "vocabulary" VALUES(1032,71,'BG2.24','It',NULL,'is not produced out of any cause. It is not new. It is ancient');
INSERT INTO "vocabulary" VALUES(1033,72,'BG2.25','अव्यक्तः',NULL,'unmanifested');
INSERT INTO "vocabulary" VALUES(1034,72,'BG2.25','अयम्',NULL,'this (Self)');
INSERT INTO "vocabulary" VALUES(1035,72,'BG2.25','अचिन्त्यः',NULL,'unthinkable');
INSERT INTO "vocabulary" VALUES(1036,72,'BG2.25','अयम्',NULL,'this');
INSERT INTO "vocabulary" VALUES(1037,72,'BG2.25','अविकार्यः',NULL,'unchangeable');
INSERT INTO "vocabulary" VALUES(1038,72,'BG2.25','अयम्',NULL,'this');
INSERT INTO "vocabulary" VALUES(1039,72,'BG2.25','उच्यते',NULL,'is said');
INSERT INTO "vocabulary" VALUES(1040,72,'BG2.25','तस्मात्',NULL,'therefore');
INSERT INTO "vocabulary" VALUES(1041,72,'BG2.25','एवम्',NULL,'thus');
INSERT INTO "vocabulary" VALUES(1042,72,'BG2.25','विदित्वा',NULL,'having known');
INSERT INTO "vocabulary" VALUES(1043,72,'BG2.25','एनम्',NULL,'this');
INSERT INTO "vocabulary" VALUES(1044,72,'BG2.25','न',NULL,'not');
INSERT INTO "vocabulary" VALUES(1045,72,'BG2.25','अनुशोचितुम्',NULL,'to grieve');
INSERT INTO "vocabulary" VALUES(1046,72,'BG2.25','अर्हसि',NULL,'(thou) oughtest.Commentary The Self is not an object of perception. It can hardly be seen by the physical eyes. Therefore');
INSERT INTO "vocabulary" VALUES(1047,72,'BG2.25','the',NULL,'Self is unmanifested. That which is seen by the eyes becomes an object of thought. As the Self cannot be perceived by the eyes');
INSERT INTO "vocabulary" VALUES(1048,72,'BG2.25','It',NULL,'is unthinkable. Milk when mixed with buttermilk changes its form. The Self cannot change Its form like milk. Hence');
INSERT INTO "vocabulary" VALUES(1049,72,'BG2.25','It',NULL,'is changeless and immutable. Therefore');
INSERT INTO "vocabulary" VALUES(1050,72,'BG2.25','thus',NULL,'understanding the Self');
INSERT INTO "vocabulary" VALUES(1051,72,'BG2.25','thou',NULL,'shouldst not mourn. Thou shouldst not think also that thou art their slayer and that they are killed by thee');
INSERT INTO "vocabulary" VALUES(1052,73,'BG2.26','अथ',NULL,'now');
INSERT INTO "vocabulary" VALUES(1053,73,'BG2.26','च',NULL,'and');
