INSERT INTO "vocabulary" VALUES(1061,73,'BG2.26','त्वम्',NULL,'thou');
INSERT INTO "vocabulary" VALUES(1062,73,'BG2.26','महाबाहो',NULL,'mightyarmed');
INSERT INTO "vocabulary" VALUES(1063,73,'BG2.26','न',NULL,'not');
INSERT INTO "vocabulary" VALUES(1064,73,'BG2.26','एवम्',NULL,'thus');
INSERT INTO "vocabulary" VALUES(1065,73,'BG2.26','शोचितुम्',NULL,'to grieve');
INSERT INTO "vocabulary" VALUES(1066,73,'BG2.26','अर्हसि',NULL,'(thou) oughtest.Commentary Lord Krishna here');
INSERT INTO "vocabulary" VALUES(1067,73,'BG2.26','for',NULL,'the sake of argument');
INSERT INTO "vocabulary" VALUES(1068,73,'BG2.26','takes',NULL,'up the popular supposition. Granting that the Self is again and again born whenever a body comes into being');
INSERT INTO "vocabulary" VALUES(1069,73,'BG2.26','and',NULL,'again and again dies whenever the body dies');
INSERT INTO "vocabulary" VALUES(1070,73,'BG2.26','O',NULL,'mightyarmed (O Arjuna of great valour and strength)');
INSERT INTO "vocabulary" VALUES(1071,73,'BG2.26','thou',NULL,'shouldst not grieve thus');
INSERT INTO "vocabulary" VALUES(1072,73,'BG2.26','because',NULL,'birth is inevitable to want is dead and death is inevitable to what is born. This is the inexorable or unrelenting Law of Nature');
INSERT INTO "vocabulary" VALUES(1073,74,'BG2.27','जातस्य',NULL,'of the born');
INSERT INTO "vocabulary" VALUES(1074,74,'BG2.27','हि',NULL,'for');
INSERT INTO "vocabulary" VALUES(1075,74,'BG2.27','ध्रुवः',NULL,'certain');
INSERT INTO "vocabulary" VALUES(1076,74,'BG2.27','मृत्युः',NULL,'death');
INSERT INTO "vocabulary" VALUES(1077,74,'BG2.27','ध्रुवम्',NULL,'certain');
INSERT INTO "vocabulary" VALUES(1078,74,'BG2.27','जन्म',NULL,'birth');
INSERT INTO "vocabulary" VALUES(1079,74,'BG2.27','मृतस्य',NULL,'of the dead');
INSERT INTO "vocabulary" VALUES(1080,74,'BG2.27','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(1081,74,'BG2.27','तस्मात्',NULL,'therefore');
