INSERT INTO "vocabulary" VALUES(1127,76,'BG2.29','एव',NULL,'also');
INSERT INTO "vocabulary" VALUES(1128,76,'BG2.29','कश्चित्',NULL,'any one.Commentary The verse may also be interpreted in this manner. He that sees');
INSERT INTO "vocabulary" VALUES(1129,76,'BG2.29','hears',NULL,'and speaks of the Self is a wonderful man. Such a man is very rare. He is one among many thousands. Thus the Self is very hard to understand');
