INSERT INTO "vocabulary" VALUES(1143,77,'BG2.30','अर्हसि',NULL,'(thou) shouldst.Commentary The body of any creature may be destroyed but the Self cannot be killed. Therefore you should not grieve regarding any creature whatever');
INSERT INTO "vocabulary" VALUES(1144,77,'BG2.30','Bhishma',NULL,'or anybody else');
