INSERT INTO "vocabulary" VALUES(1156,78,'BG2.31','अन्यत्',NULL,'other');
INSERT INTO "vocabulary" VALUES(1157,78,'BG2.31','क्षत्रियस्य',NULL,'of a Kshatriya');
INSERT INTO "vocabulary" VALUES(1158,78,'BG2.31','न',NULL,'not');
INSERT INTO "vocabulary" VALUES(1159,78,'BG2.31','विद्यते',NULL,'is.Commentary Lord Krishna now gives to Arjuna wordly reasons for fighting. Up to this time');
INSERT INTO "vocabulary" VALUES(1160,78,'BG2.31','He',NULL,'talked to Arjuna on the immortality of the Self and gave him philosophical reasons. Now He says to Arjuna');
INSERT INTO "vocabulary" VALUES(1161,78,'BG2.31','O',NULL,'Arjuna Fighting is a Kshatriyas own duty. You ought not to swerve from that duty. To a Kshatriyta (one born in the warrior or ruling class) nothing is more welcome than a righteous war. A warrior should fight');
INSERT INTO "vocabulary" VALUES(1162,79,'BG2.32','यदृच्छया',NULL,'of itself');
INSERT INTO "vocabulary" VALUES(1163,79,'BG2.32','च',NULL,'and');
