INSERT INTO "vocabulary" VALUES(1165,79,'BG2.32','स्वर्गद्वारम्',NULL,'the gate of heaven');
INSERT INTO "vocabulary" VALUES(1166,79,'BG2.32','अपावृतम्',NULL,'opened');
