INSERT INTO "vocabulary" VALUES(1172,79,'BG2.32','ईदृशम्',NULL,'such.Commentary The scriptures declare that if a Kshatriya dies for a righteous cause on the battlefield');
INSERT INTO "vocabulary" VALUES(1173,79,'BG2.32','he',NULL,'at once goes to heaven');
