INSERT INTO "vocabulary" VALUES(1183,80,'BG2.33','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(1184,80,'BG2.33','हित्वा',NULL,'having abandoned');
INSERT INTO "vocabulary" VALUES(1185,80,'BG2.33','पापम्',NULL,'sin');
INSERT INTO "vocabulary" VALUES(1186,80,'BG2.33','अवाप्स्यसि',NULL,'shall incur.Commentary The Lord reminds Arjuna of the fame he had already earned and which he would now lose if he refused to fight. Arjuna had acired great fame by fighting with Lord Siva. Arjuna proceeded on a pilgrimage to the Himalayas. He fought with Siva Who appeared in the guise of a mountaineer (Kirata) and got from Him the Pasupatastra');
INSERT INTO "vocabulary" VALUES(1187,80,'BG2.33','a',NULL,'celestial weapon');
INSERT INTO "vocabulary" VALUES(1188,81,'BG2.34','अकीर्तिम्',NULL,'dishonour');
