INSERT INTO "vocabulary" VALUES(1195,81,'BG2.34','संभावितस्य',NULL,'of the honoured');
INSERT INTO "vocabulary" VALUES(1196,81,'BG2.34','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(1197,81,'BG2.34','अकीर्तिः',NULL,'dishonour');
INSERT INTO "vocabulary" VALUES(1198,81,'BG2.34','मरणात्',NULL,'than death');
INSERT INTO "vocabulary" VALUES(1199,81,'BG2.34','अतिरिच्यते',NULL,'exceeds.Commentary The world also will ever recount thy infamy which will survive thee for a long time. Death is really preferable to disgrace to one who has been honoured as a great hero and mighty warrior with noble alities');
INSERT INTO "vocabulary" VALUES(1200,82,'BG2.35','भयात्',NULL,'from fear');
