INSERT INTO "vocabulary" VALUES(1210,82,'BG2.35','भूत्वा',NULL,'having been');
INSERT INTO "vocabulary" VALUES(1211,82,'BG2.35','यास्यसि',NULL,'will receive');
INSERT INTO "vocabulary" VALUES(1212,82,'BG2.35','लाघवम्',NULL,'lightness.Commentary Duryodhana and others will certainly think that you have fled from the battle from fear of Karna and others');
INSERT INTO "vocabulary" VALUES(1213,82,'BG2.35','but',NULL,'not through compassion and reverence for elders and teachers. Duryodhana and others who have shown great esteem to you on account of your chivalry');
INSERT INTO "vocabulary" VALUES(1214,82,'BG2.35','bravery',NULL,'and other noble alities');
INSERT INTO "vocabulary" VALUES(1215,82,'BG2.35','will',NULL,'think very lightly of you and treat you with contempt');
INSERT INTO "vocabulary" VALUES(1216,83,'BG2.36','अवाच्यवादान्',NULL,'words that are improper to be spoken');
INSERT INTO "vocabulary" VALUES(1217,83,'BG2.36','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(1218,83,'BG2.36','बहून्',NULL,'many');
INSERT INTO "vocabulary" VALUES(1219,83,'BG2.36','वदिष्यन्ति',NULL,'will say');
INSERT INTO "vocabulary" VALUES(1220,83,'BG2.36','तव',NULL,'thy');
INSERT INTO "vocabulary" VALUES(1221,83,'BG2.36','अहिताः',NULL,'enemies');
INSERT INTO "vocabulary" VALUES(1222,83,'BG2.36','निन्दन्तः',NULL,'cavilling');
INSERT INTO "vocabulary" VALUES(1223,83,'BG2.36','तव',NULL,'thy');
INSERT INTO "vocabulary" VALUES(1224,83,'BG2.36','सामर्थ्यम्',NULL,'power');
INSERT INTO "vocabulary" VALUES(1225,83,'BG2.36','ततः',NULL,'than this');
INSERT INTO "vocabulary" VALUES(1226,83,'BG2.36','दुःखतरम्',NULL,'more painful');
INSERT INTO "vocabulary" VALUES(1227,83,'BG2.36','नु',NULL,'indeed');
INSERT INTO "vocabulary" VALUES(1228,83,'BG2.36','किम्',NULL,'what.Commentary There is really no pain more unbearable and tormenting that that of slander thus incurred');
