INSERT INTO "vocabulary" VALUES(1230,84,'BG2.37','वा',NULL,'or');
INSERT INTO "vocabulary" VALUES(1231,84,'BG2.37','प्राप्स्यसि',NULL,'(thou) wilt obtain');
INSERT INTO "vocabulary" VALUES(1232,84,'BG2.37','स्वर्गम्',NULL,'heaven');
INSERT INTO "vocabulary" VALUES(1233,84,'BG2.37','जित्वा',NULL,'having conered');
INSERT INTO "vocabulary" VALUES(1234,84,'BG2.37','वा',NULL,'or');
INSERT INTO "vocabulary" VALUES(1235,84,'BG2.37','भोक्ष्यसे',NULL,'(thou) wilt enjoy');
