INSERT INTO "vocabulary" VALUES(1711,118,'BG2.71','अधिगच्छति',NULL,'attains.Commentary That man who lives destitute of longing');
INSERT INTO "vocabulary" VALUES(1712,118,'BG2.71','abandoning',NULL,'all desires');
INSERT INTO "vocabulary" VALUES(1713,118,'BG2.71','without',NULL,'the senses of I and mine');
INSERT INTO "vocabulary" VALUES(1714,118,'BG2.71','who',NULL,'is satisfied with the bare necessities of life');
INSERT INTO "vocabulary" VALUES(1715,118,'BG2.71','who',NULL,'does not care even for those bare necessities of life');
INSERT INTO "vocabulary" VALUES(1716,118,'BG2.71','who',NULL,'has no attachment even for the bare necessities of life');
INSERT INTO "vocabulary" VALUES(1717,118,'BG2.71','attains',NULL,'Moksha or eternal peace. (Cf.II.55)');
INSERT INTO "vocabulary" VALUES(1718,119,'BG2.72','एषा',NULL,'this');
INSERT INTO "vocabulary" VALUES(1719,119,'BG2.72','ब्राह्मी',NULL,'of Brahmic');
