INSERT INTO "vocabulary" VALUES(1750,120,'BG3.1','केशव',NULL,'O Kesava.Commentary In verses 49');
INSERT INTO "vocabulary" VALUES(1751,120,'BG3.1','50',NULL,'and 51 of chapter II');
INSERT INTO "vocabulary" VALUES(1752,120,'BG3.1','Lord',NULL,'Krsihna has spoken very highly about Buddhi Yoga. He again asks Arjuna to fight. That is the reason why Arjuna is perplexed now');
