INSERT INTO "vocabulary" VALUES(1767,121,'BG3.2','आप्नुयाम्',NULL,'may attain.Commentary Arjuna says to Lord Krishna');
INSERT INTO "vocabulary" VALUES(1768,121,'BG3.2','Tecah',NULL,'me one of the two');
INSERT INTO "vocabulary" VALUES(1769,121,'BG3.2','knowledge',NULL,'or action');
INSERT INTO "vocabulary" VALUES(1770,121,'BG3.2','by',NULL,'which I may attain to the highest good or bliss or Moksha. (Cf.V.I)');
