INSERT INTO "vocabulary" VALUES(1794,123,'BG3.4','नैष्कर्म्यम्',NULL,'actionlessness');
INSERT INTO "vocabulary" VALUES(1795,123,'BG3.4','पुरुषः',NULL,'man');
INSERT INTO "vocabulary" VALUES(1796,123,'BG3.4','अश्नुते',NULL,'reaches');
INSERT INTO "vocabulary" VALUES(1797,123,'BG3.4','न',NULL,'not');
