INSERT INTO "vocabulary" VALUES(1836,125,'BG3.6','Upastha',NULL,'(genitals) and Guda (anus). They are born of the Rajasic portion of the five Tanmatras or subtle elements Vak from the Akasa Tanmatra (ether)');
