INSERT INTO "vocabulary" VALUES(1838,125,'BG3.6','Padam',NULL,'from the Agni Tanmatra (fire)');
INSERT INTO "vocabulary" VALUES(1839,125,'BG3.6','Upastha',NULL,'from the Apas Tanmatra (water)');
INSERT INTO "vocabulary" VALUES(1840,125,'BG3.6','and',NULL,'Guda from the Prithivi Tanmatra (earth). That man who');
