INSERT INTO "vocabulary" VALUES(1916,130,'BG3.11','etc',NULL,'the highest good is the attainment of the knowledge of the Self which frees one from the round of births and deaths. The highest good may mean the attainment of heaven also. The fruit depends upon the motive of the aspirant');
