INSERT INTO "vocabulary" VALUES(2013,136,'BG3.17','विद्यते',NULL,'is.Commentary The sage does not depend on external objects for his happiness. He is ite satisfied with the Self. He finds his joy');
INSERT INTO "vocabulary" VALUES(2014,136,'BG3.17','bliss',NULL,'and contentment within his own Self. For such a sage who has knowledge of the Self');
INSERT INTO "vocabulary" VALUES(2015,136,'BG3.17','there',NULL,'is nothing to do. He has already done all actions. He has satisfied all his desires. He has complete satisfaction. (Cf.II.55)');
