INSERT INTO "vocabulary" VALUES(2134,144,'BG3.25','I',NULL,'will do such and such work and will get such and such fruit. But the wise man who knows the Self');
INSERT INTO "vocabulary" VALUES(2135,144,'BG3.25','serves',NULL,'not for his own end. He should so act that the world');
INSERT INTO "vocabulary" VALUES(2136,144,'BG3.25','following',NULL,'his example');
INSERT INTO "vocabulary" VALUES(2137,144,'BG3.25','would',NULL,'attain peace');
INSERT INTO "vocabulary" VALUES(2138,144,'BG3.25','purity',NULL,'of heart');
INSERT INTO "vocabulary" VALUES(2139,144,'BG3.25','divine',NULL,'light and knowledge. A wise man is one who knows the Self. (Cf.II.64III.19XVIII.49)');
INSERT INTO "vocabulary" VALUES(2140,145,'BG3.26','न',NULL,'not');
INSERT INTO "vocabulary" VALUES(2141,145,'BG3.26','बुद्धिभेदम्',NULL,'unsettlement in the mind');
