INSERT INTO "vocabulary" VALUES(3303,217,'BG5.13','कारयन्',NULL,'causing to act.Commentary All actions -- (1) Nitya Karmas These are obligatory duties. Their performance does not produce any merit but their nonperformance produces demerit. Sandhyavandana');
INSERT INTO "vocabulary" VALUES(3304,217,'BG5.13','belong',NULL,'to this category.(2) Naimittika Karmas These Karmas are performed on the occurrence of some special events such as the birth of a son');
INSERT INTO "vocabulary" VALUES(3305,217,'BG5.13','etc3',NULL,'Kamya Karmas These are optional. They are intended for the attainment of some special ends (for getting rain');
INSERT INTO "vocabulary" VALUES(3306,217,'BG5.13','etc4',NULL,'Nishiddha Karmas These are forbidden actions such as theft');
INSERT INTO "vocabulary" VALUES(3307,217,'BG5.13','drinking',NULL,'liour');
INSERT INTO "vocabulary" VALUES(3308,217,'BG5.13','etc5',NULL,'Prayaschitta Karmas Actions performed to neutralise the effects of evil actions or sins.The man who has controlled the senses renounces all actions by discrimination');
INSERT INTO "vocabulary" VALUES(3309,217,'BG5.13','by',NULL,'seeing inaction in action and rests happily in this body of nine openings (the ninegated city)');
INSERT INTO "vocabulary" VALUES(3310,217,'BG5.13','because',NULL,'he is free from cares');
INSERT INTO "vocabulary" VALUES(3311,217,'BG5.13','anxieties',NULL,'and fear and his mind is ite calm and he enjoys the supreme peace of the Eternal. In this ninegated city the Self is the king. The senses');
INSERT INTO "vocabulary" VALUES(3312,217,'BG5.13','the',NULL,'mind');
INSERT INTO "vocabulary" VALUES(3313,217,'BG5.13','the',NULL,'subconscious mind');
INSERT INTO "vocabulary" VALUES(3314,217,'BG5.13','and',NULL,'the intellect are the inhabitants or subjects.The ignorant wordly man says');
INSERT INTO "vocabulary" VALUES(3315,217,'BG5.13','I',NULL,'am resting in the easychair. The man of wisdom who has realised that the Self is distinct from the body which is a product of the five elements');
INSERT INTO "vocabulary" VALUES(3316,217,'BG5.13','I',NULL,'am resting in this body. (Cf.XVIII.17');
