INSERT INTO "vocabulary" VALUES(4430,285,'BG7.5','मे',NULL,'My');
INSERT INTO "vocabulary" VALUES(4431,285,'BG7.5','पराम्',NULL,'higher');
INSERT INTO "vocabulary" VALUES(4432,285,'BG7.5','जीवभूताम्',NULL,'the very lifeelement');
INSERT INTO "vocabulary" VALUES(4433,285,'BG7.5','महाबाहो',NULL,'O mightyarmed');
INSERT INTO "vocabulary" VALUES(4434,285,'BG7.5','यया',NULL,'by which');
INSERT INTO "vocabulary" VALUES(4435,285,'BG7.5','इदम्',NULL,'this');
INSERT INTO "vocabulary" VALUES(4436,285,'BG7.5','धार्यते',NULL,'is upheld');
INSERT INTO "vocabulary" VALUES(4437,285,'BG7.5','जगत्',NULL,'world.Commentary The eightfold Nature described in the previous verse is the inferior Nature. It constitutes the Kshetra or the field or matter. It is impure. It generates evil and causes bondage. But the superior Nature is pure. It is My very Self');
INSERT INTO "vocabulary" VALUES(4438,285,'BG7.5','Kshetrajna',NULL,'(knower of the field or Spirit) by which life is sustained');
INSERT INTO "vocabulary" VALUES(4439,285,'BG7.5','and',NULL,'that which enters within the whole world and upholds it. It is the very lifeelement or the principle of Selfconsciousness');
INSERT INTO "vocabulary" VALUES(4440,285,'BG7.5','by',NULL,'which this universe is sustained');
INSERT INTO "vocabulary" VALUES(4441,286,'BG7.6','एतद्योनीनि',NULL,'those of which these two (Prakritis) are the womb');
INSERT INTO "vocabulary" VALUES(4442,286,'BG7.6','भूतानि',NULL,'beings');
