INSERT INTO "vocabulary" VALUES(4447,286,'BG7.6','कृत्स्नस्य',NULL,'of the whole');
INSERT INTO "vocabulary" VALUES(4448,286,'BG7.6','जगतः',NULL,'of the world');
INSERT INTO "vocabulary" VALUES(4449,286,'BG7.6','प्रभवः',NULL,'source');
INSERT INTO "vocabulary" VALUES(4450,286,'BG7.6','प्रलयः',NULL,'dissolution');
INSERT INTO "vocabulary" VALUES(4451,286,'BG7.6','तथा',NULL,'also.Commentary These two Natures');
INSERT INTO "vocabulary" VALUES(4452,286,'BG7.6','the',NULL,'inferior and the superior');
INSERT INTO "vocabulary" VALUES(4453,286,'BG7.6','are',NULL,'the womb of all beings. As I am the source of these two Prakritis or Natures also');
INSERT INTO "vocabulary" VALUES(4454,286,'BG7.6','I',NULL,'am the cause of this universe. The whole universe originates from Me and dissolves in Me.In the Brahma Sutras (chapter 1');
INSERT INTO "vocabulary" VALUES(4455,286,'BG7.6','section',NULL,'1');
INSERT INTO "vocabulary" VALUES(4456,286,'BG7.6','aphorism',NULL,'2) it is said');
INSERT INTO "vocabulary" VALUES(4457,286,'BG7.6','Janmadyasya',NULL,'yatah meaning that Brahman is that omniscient and omnipotent cause from which proceed the origin');
INSERT INTO "vocabulary" VALUES(4458,286,'BG7.6','subsistence',NULL,'and dissolution of this world.Just as the mind is the material cause and also the seer (Drashta) for the objects seen in a dream');
INSERT INTO "vocabulary" VALUES(4459,286,'BG7.6','so',NULL,'also Isvara is the material cause of this world (UpadanaKarana) and also the seer (Drashta). He is also the efficient or the instrumental cause (NimittaKarana). (Cf.XIV.3)');
INSERT INTO "vocabulary" VALUES(4460,287,'BG7.7','मत्तः',NULL,'than Me');
INSERT INTO "vocabulary" VALUES(4461,287,'BG7.7','परतरम्',NULL,'higher');
