INSERT INTO "vocabulary" VALUES(4464,287,'BG7.7','किञ्चित्',NULL,'anyone');
INSERT INTO "vocabulary" VALUES(4465,287,'BG7.7','अस्ति',NULL,'is');
INSERT INTO "vocabulary" VALUES(4466,287,'BG7.7','धनञ्जय',NULL,'O Dhananjaya');
INSERT INTO "vocabulary" VALUES(4467,287,'BG7.7','मयि',NULL,'in Me');
INSERT INTO "vocabulary" VALUES(4468,287,'BG7.7','सर्वम्',NULL,'all');
INSERT INTO "vocabulary" VALUES(4469,287,'BG7.7','इदम्',NULL,'this');
INSERT INTO "vocabulary" VALUES(4470,287,'BG7.7','प्रोतम्',NULL,'is strung');
INSERT INTO "vocabulary" VALUES(4471,287,'BG7.7','सूत्रे',NULL,'on a string');
INSERT INTO "vocabulary" VALUES(4472,287,'BG7.7','मणिगणाः',NULL,'clusters of gems');
INSERT INTO "vocabulary" VALUES(4473,287,'BG7.7','इव',NULL,'like.Commentary There is no other cause of the universe but Me. I alone am the the cause of the universe. This illustration of gems and thread illustrates only the idea that all beings and the whole world are threaded on the Lord. The thread is not the cause of the gems. As Brahman is all in all there is nothing whatever higher than It');
INSERT INTO "vocabulary" VALUES(4474,288,'BG7.8','रसः',NULL,'sapidity');
INSERT INTO "vocabulary" VALUES(4475,288,'BG7.8','अहम्',NULL,'I');
INSERT INTO "vocabulary" VALUES(4476,288,'BG7.8','अप्सु',NULL,'in water');
INSERT INTO "vocabulary" VALUES(4477,288,'BG7.8','कौन्तेय',NULL,'O Kaunteya (son of Kunti)');
INSERT INTO "vocabulary" VALUES(4478,288,'BG7.8','प्रभा',NULL,'light');
