INSERT INTO "vocabulary" VALUES(7016,426,'BG11.12','महात्मनः',NULL,'of the mighty Being (great soul).Commentary Divi here means in the Antariksha or the sky.Mahatma here refers to the great Soul or the mighty Being');
INSERT INTO "vocabulary" VALUES(7017,426,'BG11.12','the',NULL,'Cosmic Form');
INSERT INTO "vocabulary" VALUES(7018,427,'BG11.13','तत्र',NULL,'there');
