INSERT INTO "vocabulary" VALUES(7022,427,'BG11.13','प्रविभक्तम्',NULL,'divided');
INSERT INTO "vocabulary" VALUES(7023,427,'BG11.13','अनेकधा',NULL,'in many groups');
INSERT INTO "vocabulary" VALUES(7024,427,'BG11.13','अपश्यत्',NULL,'saw');
INSERT INTO "vocabulary" VALUES(7025,427,'BG11.13','देवदेवस्य',NULL,'of the God of gods');
INSERT INTO "vocabulary" VALUES(7026,427,'BG11.13','शरीरे',NULL,'in the body');
INSERT INTO "vocabulary" VALUES(7027,427,'BG11.13','पाण्डवः',NULL,'son of Pandu');
INSERT INTO "vocabulary" VALUES(7028,427,'BG11.13','तदा',NULL,'then.Commentary Tatra There -- in the Cosmic Form.Anekadha Many groups -- gods');
INSERT INTO "vocabulary" VALUES(7029,427,'BG11.13','men',NULL,'and other species of beings.Arjuna beheld all forms as the forms of the Lord');
INSERT INTO "vocabulary" VALUES(7030,427,'BG11.13','all',NULL,'heads as His heads');
INSERT INTO "vocabulary" VALUES(7031,427,'BG11.13','all',NULL,'eyes as His eyes');
INSERT INTO "vocabulary" VALUES(7032,427,'BG11.13','all',NULL,'hands as His hands');
INSERT INTO "vocabulary" VALUES(7033,427,'BG11.13','all',NULL,'feet as His feet');
INSERT INTO "vocabulary" VALUES(7034,427,'BG11.13','every',NULL,'part of every body as the limb of the Lords divine form. Wherever he looked he beheld nothing but the Lord. He got mystic divine knowledge.Sanjaya has given a truly graphic description of the Cosmic Form. Yet');
INSERT INTO "vocabulary" VALUES(7035,427,'BG11.13','it',NULL,'would be futile to grasp it with the finite mind. It is a transcendental vision');
INSERT INTO "vocabulary" VALUES(7036,427,'BG11.13','beyond',NULL,'the reach of the mind and senses. It has to be realised in Samadhi');
INSERT INTO "vocabulary" VALUES(7037,428,'BG11.14','ततः',NULL,'then');
INSERT INTO "vocabulary" VALUES(7038,428,'BG11.14','सः',NULL,'he');
INSERT INTO "vocabulary" VALUES(7039,428,'BG11.14','विस्मयाविष्टः',NULL,'filled with wonder');
INSERT INTO "vocabulary" VALUES(7040,428,'BG11.14','हृष्टरोमा',NULL,'with hair standing on end');
INSERT INTO "vocabulary" VALUES(7041,428,'BG11.14','धनञ्जयः',NULL,'Arjuna');
INSERT INTO "vocabulary" VALUES(7042,428,'BG11.14','प्रणम्य',NULL,'having prostrated');
INSERT INTO "vocabulary" VALUES(7043,428,'BG11.14','शिरसा',NULL,'with (his) head');
INSERT INTO "vocabulary" VALUES(7044,428,'BG11.14','देवम्',NULL,'the God');
INSERT INTO "vocabulary" VALUES(7045,428,'BG11.14','कृताञ्जलिः',NULL,'with joined palms');
INSERT INTO "vocabulary" VALUES(7046,428,'BG11.14','अभाषत',NULL,'spoke.Commentary Tatah Then');
INSERT INTO "vocabulary" VALUES(7047,428,'BG11.14','having',NULL,'seen the Cosmic Form.Arjuna joined his palms in order to do prostration to the Cosmic Form. The great hero had attained true humility which the bowed head and joined palms represented');
INSERT INTO "vocabulary" VALUES(7048,428,'BG11.14','and',NULL,'which is the essential ingredient of devotion');
