INSERT INTO "vocabulary" VALUES(7061,429,'BG11.15','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(7062,429,'BG11.15','सर्वान्',NULL,'all');
INSERT INTO "vocabulary" VALUES(7063,429,'BG11.15','उरगान्',NULL,'serpents');
INSERT INTO "vocabulary" VALUES(7064,429,'BG11.15','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(7065,429,'BG11.15','दिव्यान्',NULL,'divine.Commentary Arjuna describes his own experience of the Cosmic Form in this and the following verses');
INSERT INTO "vocabulary" VALUES(7066,429,'BG11.15','15',NULL,'to 31.Bhutaviseshasanghan Hosts of various classes of beings');
INSERT INTO "vocabulary" VALUES(7067,429,'BG11.15','both',NULL,'animate and inanimate. These numerous entities are in Thy Cosmic Form');
INSERT INTO "vocabulary" VALUES(7068,429,'BG11.15','like',NULL,'hairs on the human body.Brahma');
INSERT INTO "vocabulary" VALUES(7069,429,'BG11.15','the',NULL,'fourfaced');
INSERT INTO "vocabulary" VALUES(7070,429,'BG11.15','the',NULL,'Lord of all creatures');
INSERT INTO "vocabulary" VALUES(7071,429,'BG11.15','is',NULL,'seated in the centre of the earthlotus on the Meru which forms the thalamus as it were of the earthlotus.Sages');
INSERT INTO "vocabulary" VALUES(7072,429,'BG11.15','such',NULL,'as Vasishtha. Serpents');
INSERT INTO "vocabulary" VALUES(7073,429,'BG11.15','such',NULL,'as Vasuki.Moreover --');
