INSERT INTO "vocabulary" VALUES(7079,430,'BG11.16','अनन्तरूपम्',NULL,'of boundless form');
INSERT INTO "vocabulary" VALUES(7080,430,'BG11.16','न',NULL,'not');
INSERT INTO "vocabulary" VALUES(7081,430,'BG11.16','अनत्म्',NULL,'end');
INSERT INTO "vocabulary" VALUES(7082,430,'BG11.16','न',NULL,'not');
INSERT INTO "vocabulary" VALUES(7083,430,'BG11.16','मध्यम्',NULL,'middle');
INSERT INTO "vocabulary" VALUES(7084,430,'BG11.16','न',NULL,'not');
INSERT INTO "vocabulary" VALUES(7085,430,'BG11.16','तव',NULL,'Thy');
INSERT INTO "vocabulary" VALUES(7086,430,'BG11.16','आदिम्',NULL,'origin');
INSERT INTO "vocabulary" VALUES(7087,430,'BG11.16','पश्यामि',NULL,'(I) see');
INSERT INTO "vocabulary" VALUES(7088,430,'BG11.16','विश्वेश्वर',NULL,'O Lord of the universe');
INSERT INTO "vocabulary" VALUES(7089,430,'BG11.16','विश्वरूप',NULL,'O Cosmic Form.Commentary A thing that is limited by space and time has a begining');
INSERT INTO "vocabulary" VALUES(7090,430,'BG11.16','a',NULL,'middle and an end');
INSERT INTO "vocabulary" VALUES(7091,430,'BG11.16','but',NULL,'the Lord is omnipresent and eternal. He exists in the three periods of time -- past');
INSERT INTO "vocabulary" VALUES(7092,430,'BG11.16','present',NULL,'and future');
INSERT INTO "vocabulary" VALUES(7093,430,'BG11.16','but',NULL,'is not limited by time and space. Therefore He has neither a beginning nor middle nor end.Arjuna could have this divine vision only with the help of the divine eye bestowed upon him by the Lord. He who has supreme devotion to the Lord and on whom the Lord showers His grace can enjoy this wondrous vision');
INSERT INTO "vocabulary" VALUES(7094,431,'BG11.17','किरीटिनम्',NULL,'one with diadem');
INSERT INTO "vocabulary" VALUES(7095,431,'BG11.17','गदिनम्',NULL,'with club');
INSERT INTO "vocabulary" VALUES(7096,431,'BG11.17','चक्रिणम्',NULL,'with discus');
INSERT INTO "vocabulary" VALUES(7097,431,'BG11.17','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(7098,431,'BG11.17','तेजोराशिम्',NULL,'a mass of radiance');
INSERT INTO "vocabulary" VALUES(7099,431,'BG11.17','सर्वतः',NULL,'everywhere');
INSERT INTO "vocabulary" VALUES(7100,431,'BG11.17','दीप्तिमन्तम्',NULL,'shining');
