INSERT INTO "vocabulary" VALUES(7103,431,'BG11.17','दुर्निरीक्ष्यम्',NULL,'very hard to look at');
INSERT INTO "vocabulary" VALUES(7104,431,'BG11.17','समन्तात्',NULL,'all round');
INSERT INTO "vocabulary" VALUES(7105,431,'BG11.17','दीप्तानलार्कद्युतिम्',NULL,'blazing like burning fire and sun');
INSERT INTO "vocabulary" VALUES(7106,431,'BG11.17','अप्रमेयम्',NULL,'immeasurable.Commentary Kiritam is a special ornament for the head');
INSERT INTO "vocabulary" VALUES(7107,431,'BG11.17','the',NULL,'crown.Arjuna had worshipped the Lord as having a crown');
INSERT INTO "vocabulary" VALUES(7108,431,'BG11.17','club',NULL,'and discus and the Lord showed him the same form now. He is in all forms and He is beyond all forms as the transcendental Reality. Who can comprehend His GloryTejorasim A mass of splendour that cannot be perceived without the inner divine eye of intuition.Aprameyam Immeasurable');
INSERT INTO "vocabulary" VALUES(7109,431,'BG11.17','whose',NULL,'limits cannot be fixed.I infer from this vision of Thy power of Yoga that Thu art the Imperishable');
