INSERT INTO "vocabulary" VALUES(7121,432,'BG11.18','शाश्वतधर्मगोप्ता',NULL,'Protector of the Eternal Dharma');
INSERT INTO "vocabulary" VALUES(7122,432,'BG11.18','सनातनः',NULL,'ancient');
INSERT INTO "vocabulary" VALUES(7123,432,'BG11.18','त्वम्',NULL,'Thou');
INSERT INTO "vocabulary" VALUES(7124,432,'BG11.18','पुरुषः',NULL,'Purusha');
INSERT INTO "vocabulary" VALUES(7125,432,'BG11.18','मतः',NULL,'thought');
INSERT INTO "vocabulary" VALUES(7126,432,'BG11.18','मे',NULL,'of me.Commentary VisvasyaNidhaanam Treasurehouse of this universe');
INSERT INTO "vocabulary" VALUES(7127,432,'BG11.18','also',NULL,'means abode or refuge or the substratum of this universe. It is because of this that all the beings in the universe are preserved and protected. He is the inexhaustibel source to Whom the devotee turns at all times. Deluded indeed are they that ignore this divine treasurehouse and runa fter the shadow of the objects of the senses which do not contain even an iota of pleasure.Veditavyam To be known by the aspirants or seekrs of liberation');
INSERT INTO "vocabulary" VALUES(7128,432,'BG11.18','through',NULL,'Sravana (hearing of the scriptures)');
INSERT INTO "vocabulary" VALUES(7129,432,'BG11.18','Manana',NULL,'(reflection) and Nididhyasana (meditation).Avyayah means inexhaustible');
