INSERT INTO "vocabulary" VALUES(7138,433,'BG11.19','स्वतेजसा',NULL,'with Thy radiance');
INSERT INTO "vocabulary" VALUES(7139,433,'BG11.19','विश्वम्',NULL,'the universe');
INSERT INTO "vocabulary" VALUES(7140,433,'BG11.19','इदम्',NULL,'this');
INSERT INTO "vocabulary" VALUES(7141,433,'BG11.19','तपन्तम्',NULL,'heating.Commentary Anantabahu Having endless arms. This denotes that the multiplicity of His limbs are endless');
