INSERT INTO "vocabulary" VALUES(7176,435,'BG11.21','स्तुतिभिः',NULL,'with hymns');
INSERT INTO "vocabulary" VALUES(7177,435,'BG11.21','पुष्कलाभिः',NULL,'complete.Commentary Pushkalabhih means complete or wellworded praises or praises full of deep meanings.Great sages like Narada and perfected ones like Kapila praise Thee with inspiring hymns');
INSERT INTO "vocabulary" VALUES(7178,436,'BG11.22','रुद्रादित्याः',NULL,'Rudras and Adityas');
INSERT INTO "vocabulary" VALUES(7179,436,'BG11.22','वसवः',NULL,'Vasus');
