INSERT INTO "vocabulary" VALUES(7193,436,'BG11.22','विस्मिताः',NULL,'astonished');
INSERT INTO "vocabulary" VALUES(7194,436,'BG11.22','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(7195,436,'BG11.22','एव',NULL,'even');
INSERT INTO "vocabulary" VALUES(7196,436,'BG11.22','सर्वे',NULL,'all.Commentary Sadhyas are a class of gods of whom Brahma is the chief.Visvedevas are ten gods who in Vedic times were considered as protectors of human beings. They were called guardians of the world. They were givers of plenty to the human beings. Their names are Krata');
INSERT INTO "vocabulary" VALUES(7197,436,'BG11.22','Adrava',NULL,'and Pururava.The two Asvins');
INSERT INTO "vocabulary" VALUES(7198,436,'BG11.22','born',NULL,'of Prabha (light)');
INSERT INTO "vocabulary" VALUES(7199,436,'BG11.22','daughter',NULL,'of Tushta and the Sun');
INSERT INTO "vocabulary" VALUES(7200,436,'BG11.22','are',NULL,'the physicians of the gods.Rudras');
INSERT INTO "vocabulary" VALUES(7201,436,'BG11.22','Vasus',NULL,'and Maruts -- see tenth chapter');
INSERT INTO "vocabulary" VALUES(7202,436,'BG11.22','verses',NULL,'21 and 23.Ushmapa A class of manes. They accept the food offered in the Sraaddha (anniversary) ceremony or the obseies');
INSERT INTO "vocabulary" VALUES(7203,436,'BG11.22','while',NULL,'it is hot. Hence they are called Ushmapas. There are seven groups of manes.Gandharvas are celestial singers such as Haha and Huhu.Yakshas such as Kubera (the god of wealth) Asuras such as Virochana perfected ones such as Kapila');
INSERT INTO "vocabulary" VALUES(7204,437,'BG11.23','रूपम्',NULL,'form');
INSERT INTO "vocabulary" VALUES(7205,437,'BG11.23','महत्',NULL,'immeasurable');
INSERT INTO "vocabulary" VALUES(7206,437,'BG11.23','ते',NULL,'Thy');
