INSERT INTO "vocabulary" VALUES(7208,437,'BG11.23','महाबाहो',NULL,'O,mightyarmed');
INSERT INTO "vocabulary" VALUES(7209,437,'BG11.23','बहुबाहूरुपादम्',NULL,'with many arms');
INSERT INTO "vocabulary" VALUES(7210,437,'BG11.23','thighs',NULL,'and feet');
INSERT INTO "vocabulary" VALUES(7211,437,'BG11.23','बहूदरम्',NULL,'with many stomachs. बहुदंष्ट्राकरालम् fearful with many teeth');
INSERT INTO "vocabulary" VALUES(7212,437,'BG11.23','दृष्ट्वा',NULL,'having seen');
INSERT INTO "vocabulary" VALUES(7213,437,'BG11.23','लोकाः',NULL,'the worlds');
