INSERT INTO "vocabulary" VALUES(7215,437,'BG11.23','तथा',NULL,'also');
INSERT INTO "vocabulary" VALUES(7216,437,'BG11.23','अहम्',NULL,'I.Commentary Lokah The worlds -- all living beings in the world. Here is the cause of my fear. Arjuna describes below the nature of the Cosmic Form which has caused terror in his heart');
INSERT INTO "vocabulary" VALUES(7217,438,'BG11.24','नभःस्पृशम्',NULL,'touching the sky');
