INSERT INTO "vocabulary" VALUES(7451,450,'BG11.36','सिद्धसङ्घाः',NULL,'the hosts of the perfected ones.Commentary Praise description of the glory of the Lord. The Lord is the object worthy of adortion');
INSERT INTO "vocabulary" VALUES(7452,450,'BG11.36','love',NULL,'and delight');
