INSERT INTO "vocabulary" VALUES(7587,456,'BG11.42','अप्रमेयम्',NULL,'immeasurable.Commentary Arjuna');
INSERT INTO "vocabulary" VALUES(7588,456,'BG11.42','beholding',NULL,'the Cosmic Form of Lord Krishna');
INSERT INTO "vocabulary" VALUES(7589,456,'BG11.42','seeks',NULL,'forgiveness for his past familiar conduct. He says');
INSERT INTO "vocabulary" VALUES(7590,456,'BG11.42','I',NULL,'have been stupid. I have treated Thee with familiarity');
INSERT INTO "vocabulary" VALUES(7591,456,'BG11.42','not',NULL,'knowing Thy greatness. I have taken Thee as my friend on account of misconception. I have behaved badly with Thee. Thou art the origin of this universe and yet I have joked with Thee. I have taken undue liberties with Thee. Kindly forgive me');
INSERT INTO "vocabulary" VALUES(7592,456,'BG11.42','O',NULL,'Lord.Tat All those offences.Achyuta He who is unchanging.In company In the presence of others.Aprameyam Immeasurable. He Who has unthinkable glory and splendour');
