INSERT INTO "vocabulary" VALUES(7628,458,'BG11.44','अर्हसि',NULL,'(Thou) shouldst');
INSERT INTO "vocabulary" VALUES(7629,458,'BG11.44','देव',NULL,'O God');
INSERT INTO "vocabulary" VALUES(7630,458,'BG11.44','सोढुम्',NULL,'to bear.Commentary O Lord');
INSERT INTO "vocabulary" VALUES(7631,458,'BG11.44','take',NULL,'me to Thy bosom as a mother does her child. Forgive me for all tht I have hitherto spoken or done. Forgive my faults. Please overlook my past mistakes. I have done this through ignorance. Now I have come to Thee in submission. I beg Your pardon now');
INSERT INTO "vocabulary" VALUES(7632,459,'BG11.45','अदृष्टपूर्वम्',NULL,'what was never seen before');
