INSERT INTO "vocabulary" VALUES(7647,459,'BG11.45','प्रसीद',NULL,'have mercy');
INSERT INTO "vocabulary" VALUES(7648,459,'BG11.45','देवेश',NULL,'O Lord of the gods');
INSERT INTO "vocabulary" VALUES(7649,459,'BG11.45','जगन्निवास',NULL,'O Aboe of the universe.Commentary For an ordinary man the Cosmic Form (Vision) is overwhelming and terrifying but for a Yogi it is encouraging');
INSERT INTO "vocabulary" VALUES(7650,459,'BG11.45','strengthening',NULL,'and soulelevating.Arjuna says The Cosmic Form was never before seen by me. Show me only that form which Thou wearest as my friend');
INSERT INTO "vocabulary" VALUES(7651,460,'BG11.46','किरीटिनम्',NULL,'wearing crown');
INSERT INTO "vocabulary" VALUES(7652,460,'BG11.46','गदिनम्',NULL,'bearing a mace');
INSERT INTO "vocabulary" VALUES(7653,460,'BG11.46','चक्रहस्तम्',NULL,'with a discus in the hand');
INSERT INTO "vocabulary" VALUES(7654,460,'BG11.46','इच्छामि',NULL,'(I) desire');
INSERT INTO "vocabulary" VALUES(7655,460,'BG11.46','त्वाम्',NULL,'Thee');
INSERT INTO "vocabulary" VALUES(7656,460,'BG11.46','द्रष्टुम्',NULL,'to see');
INSERT INTO "vocabulary" VALUES(7657,460,'BG11.46','अहम्',NULL,'I');
INSERT INTO "vocabulary" VALUES(7658,460,'BG11.46','तथैव',NULL,'as before');
INSERT INTO "vocabulary" VALUES(7659,460,'BG11.46','तेनैव',NULL,'that same');
INSERT INTO "vocabulary" VALUES(7660,460,'BG11.46','रूपेण',NULL,'of form');
INSERT INTO "vocabulary" VALUES(7661,460,'BG11.46','चतुर्भुजेन',NULL,'(by) fourarmed');
INSERT INTO "vocabulary" VALUES(7662,460,'BG11.46','सहस्रबाहो',NULL,'O thousandarmed');
INSERT INTO "vocabulary" VALUES(7663,460,'BG11.46','भव',NULL,'be');
INSERT INTO "vocabulary" VALUES(7664,460,'BG11.46','विश्वमूर्ते',NULL,'O Universal Form.Commentary Arjuna says O Lord in the Cosmic Form I do not know where to turn and to whom to address myself. I am frightened. I am longing to see Thee with conch');
INSERT INTO "vocabulary" VALUES(7665,460,'BG11.46','mace',NULL,'and lotus. Withdraw Thy Cosmic Form. Assume that same fourarmed form as before.Spiritual aspirants are ofen impatient to have the highest spiritual experiences immediately they begin their Sadhana. This is wrong. They will not be able to withstand the great power that will,surge into them. Be patientO thousandarmed refers to the Cosmic Form');
INSERT INTO "vocabulary" VALUES(7666,461,'BG11.47','मया',NULL,'by Me');
INSERT INTO "vocabulary" VALUES(7667,461,'BG11.47','प्रसन्नेन',NULL,'gracious');
INSERT INTO "vocabulary" VALUES(7668,461,'BG11.47','तव',NULL,'to thee');
INSERT INTO "vocabulary" VALUES(7669,461,'BG11.47','अर्जुन',NULL,'O Arjuna');
