INSERT INTO "vocabulary" VALUES(7673,461,'BG11.47','दर्शितम्',NULL,'has been shown');
INSERT INTO "vocabulary" VALUES(7674,461,'BG11.47','आत्मयोगात्',NULL,'by My own Yogic power');
INSERT INTO "vocabulary" VALUES(7675,461,'BG11.47','तेजोमयम्',NULL,'full of splendour');
INSERT INTO "vocabulary" VALUES(7676,461,'BG11.47','विश्वम्',NULL,'universal');
INSERT INTO "vocabulary" VALUES(7677,461,'BG11.47','अनन्तम्',NULL,'endless');
INSERT INTO "vocabulary" VALUES(7678,461,'BG11.47','आद्यम्',NULL,'primeval');
INSERT INTO "vocabulary" VALUES(7679,461,'BG11.47','यत्',NULL,'which');
INSERT INTO "vocabulary" VALUES(7680,461,'BG11.47','मे',NULL,'of Me');
INSERT INTO "vocabulary" VALUES(7681,461,'BG11.47','त्वत्',NULL,'from thee');
INSERT INTO "vocabulary" VALUES(7682,461,'BG11.47','अन्येन',NULL,'by another');
INSERT INTO "vocabulary" VALUES(7683,461,'BG11.47','न',NULL,'not');
INSERT INTO "vocabulary" VALUES(7684,461,'BG11.47','दृष्टपूर्वम्',NULL,'seen before.Commentary Lord Krishna eulogises the Cosmic Form because Arjuna should be regarded to have achieved all his ends by seeing this Cosmic Form.It is also an inducement to all spiritual aspirants to strive to attain this sublime vision. What they should do is explained by the Lord in verse 53 to 55');
INSERT INTO "vocabulary" VALUES(7685,462,'BG11.48','न',NULL,'not');
INSERT INTO "vocabulary" VALUES(7686,462,'BG11.48','वेदयज्ञाध्ययनैः',NULL,'by the study of the Vedas and of Yajnas');
