INSERT INTO "vocabulary" VALUES(7694,462,'BG11.48','उग्रैः',NULL,'severe');
INSERT INTO "vocabulary" VALUES(7695,462,'BG11.48','एवंरूपः',NULL,'in such form');
INSERT INTO "vocabulary" VALUES(7696,462,'BG11.48','शक्यः',NULL,'(am) possible');
INSERT INTO "vocabulary" VALUES(7697,462,'BG11.48','अहम्',NULL,'I');
INSERT INTO "vocabulary" VALUES(7698,462,'BG11.48','नृलोके',NULL,'in the world of men');
INSERT INTO "vocabulary" VALUES(7699,462,'BG11.48','द्रष्टुम्',NULL,'to be seen');
INSERT INTO "vocabulary" VALUES(7700,462,'BG11.48','त्वत्',NULL,'than thee');
INSERT INTO "vocabulary" VALUES(7701,462,'BG11.48','अन्येन',NULL,'by another');
INSERT INTO "vocabulary" VALUES(7702,462,'BG11.48','कुरुप्रवीर',NULL,'O great hero of the Kurus.Commentary Mere cramming of the texts of the Vedas without knowing the meaning will not do. A study of the sacrifices also is necessary. One should know the meaning of these');
INSERT INTO "vocabulary" VALUES(7703,462,'BG11.48','alsoDana',NULL,'Charity such as a Tula Purusha (gift of gold eal in weight of a man) Kanyadana (gift of ones daughther in marriage)');
INSERT INTO "vocabulary" VALUES(7704,462,'BG11.48','gift',NULL,'of a cow');
INSERT INTO "vocabulary" VALUES(7705,462,'BG11.48','etcKriya',NULL,'Rituals such as Agnihotra.Tapas Such as the Chandrayana Vrata. (This is a kind of Vrata or observance. The daily consumption of food is reduced by one mouthful every day for the dark half of the month beginning with the fullmoon. Then the food is increased by one mouthful every day during the bright fortnight during the increase of the moon. This Vrata (observance) is a great purifier of the mind. It destroys sins.)');
INSERT INTO "vocabulary" VALUES(7706,463,'BG11.49','मा',NULL,'not');
INSERT INTO "vocabulary" VALUES(7707,463,'BG11.49','ते',NULL,'thee');
INSERT INTO "vocabulary" VALUES(7708,463,'BG11.49','व्यथा',NULL,'fear');
INSERT INTO "vocabulary" VALUES(7709,463,'BG11.49','मा',NULL,'not');
INSERT INTO "vocabulary" VALUES(7710,463,'BG11.49','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(7711,463,'BG11.49','विमूढभावः',NULL,'bewildered state');
