INSERT INTO "vocabulary" VALUES(7714,463,'BG11.49','घोरम्',NULL,'terrible');
INSERT INTO "vocabulary" VALUES(7715,463,'BG11.49','ईदृक्',NULL,'such');
INSERT INTO "vocabulary" VALUES(7716,463,'BG11.49','मम',NULL,'My');
