INSERT INTO "vocabulary" VALUES(7718,463,'BG11.49','व्यपेतभीः',NULL,'with (thy) fear dispelled');
INSERT INTO "vocabulary" VALUES(7719,463,'BG11.49','प्रीतमनाः',NULL,'with gladdened heart');
INSERT INTO "vocabulary" VALUES(7720,463,'BG11.49','पुनः',NULL,'again');
INSERT INTO "vocabulary" VALUES(7721,463,'BG11.49','त्वम्',NULL,'thou');
INSERT INTO "vocabulary" VALUES(7722,463,'BG11.49','तत्',NULL,'that');
INSERT INTO "vocabulary" VALUES(7723,463,'BG11.49','एव',NULL,'even');
INSERT INTO "vocabulary" VALUES(7724,463,'BG11.49','मे',NULL,'My');
INSERT INTO "vocabulary" VALUES(7725,463,'BG11.49','रूपम्',NULL,'form');
INSERT INTO "vocabulary" VALUES(7726,463,'BG11.49','इदम्',NULL,'this');
INSERT INTO "vocabulary" VALUES(7727,463,'BG11.49','प्रपश्य',NULL,'behold.Commentary Former form is the form with four hands with conch');
INSERT INTO "vocabulary" VALUES(7728,463,'BG11.49','club',NULL,'or mace and lotus.The Lord was Arjuna in a state of terror. Therefore');
INSERT INTO "vocabulary" VALUES(7729,463,'BG11.49','He',NULL,'withdrew the Cosmic Form and assumed His usual gentle form. He consoled Arjuna and spoke sweet');
INSERT INTO "vocabulary" VALUES(7730,463,'BG11.49','loving',NULL,'words');
INSERT INTO "vocabulary" VALUES(7731,464,'BG11.50','इति',NULL,'thus');
INSERT INTO "vocabulary" VALUES(7732,464,'BG11.50','अर्जुनम्',NULL,'to Arjuna');
INSERT INTO "vocabulary" VALUES(7733,464,'BG11.50','वासुदेवः',NULL,'Vaasudeva');
INSERT INTO "vocabulary" VALUES(7734,464,'BG11.50','तथा',NULL,'so');
INSERT INTO "vocabulary" VALUES(7735,464,'BG11.50','उक्त्वा',NULL,'having spoken');
INSERT INTO "vocabulary" VALUES(7736,464,'BG11.50','स्वकम्',NULL,'His own');
INSERT INTO "vocabulary" VALUES(7737,464,'BG11.50','रूपम्',NULL,'form');
INSERT INTO "vocabulary" VALUES(7738,464,'BG11.50','दर्शयामास',NULL,'showed');
INSERT INTO "vocabulary" VALUES(7739,464,'BG11.50','भूयः',NULL,'again');
INSERT INTO "vocabulary" VALUES(7740,464,'BG11.50','आश्वासयामास',NULL,'consoled');
INSERT INTO "vocabulary" VALUES(7741,464,'BG11.50','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(7742,464,'BG11.50','भीतम्',NULL,'who was terrified');
INSERT INTO "vocabulary" VALUES(7743,464,'BG11.50','एनम्',NULL,'him');
INSERT INTO "vocabulary" VALUES(7744,464,'BG11.50','भूत्वा',NULL,'having become');
INSERT INTO "vocabulary" VALUES(7745,464,'BG11.50','पुनः',NULL,'again');
INSERT INTO "vocabulary" VALUES(7746,464,'BG11.50','सौम्यवपुः',NULL,'of gentle form');
INSERT INTO "vocabulary" VALUES(7747,464,'BG11.50','महात्मा',NULL,'the greatsouled One.Commentary His own form His form as the son of Vasudeva');
INSERT INTO "vocabulary" VALUES(7748,465,'BG11.51','दृष्ट्वा',NULL,'having seen');
INSERT INTO "vocabulary" VALUES(7749,465,'BG11.51','इदम्',NULL,'this');
INSERT INTO "vocabulary" VALUES(7750,465,'BG11.51','मानुषम्',NULL,'human');
INSERT INTO "vocabulary" VALUES(7751,465,'BG11.51','रूपम्',NULL,'form');
INSERT INTO "vocabulary" VALUES(7752,465,'BG11.51','तव',NULL,'Thy');
INSERT INTO "vocabulary" VALUES(7753,465,'BG11.51','सौम्यम्',NULL,'gentle');
INSERT INTO "vocabulary" VALUES(7754,465,'BG11.51','जनार्दन',NULL,'O Krishna');
INSERT INTO "vocabulary" VALUES(7755,465,'BG11.51','इदानीम्',NULL,'now');
INSERT INTO "vocabulary" VALUES(7756,465,'BG11.51','अस्मि',NULL,'(I) am');
INSERT INTO "vocabulary" VALUES(7757,465,'BG11.51','संवृत्तः',NULL,'composed');
INSERT INTO "vocabulary" VALUES(7758,465,'BG11.51','सचेताः',NULL,'with mind');
INSERT INTO "vocabulary" VALUES(7759,465,'BG11.51','प्रकृतिम्',NULL,'to nature');
INSERT INTO "vocabulary" VALUES(7760,465,'BG11.51','गतः',NULL,'restored.Commentary Arjuna says to Lord Krishna O Lord');
INSERT INTO "vocabulary" VALUES(7761,465,'BG11.51','I',NULL,'now behold Thy human form. Now my thoughts are collected and I am serene. I can speak. My senses perform their proper functions. My fear has vanished. Thou hast treated me as a mother would treat her erring child whom she embraces and nurses. Just as the calf rejoices when it beholds its mother who was missing for some days');
INSERT INTO "vocabulary" VALUES(7762,465,'BG11.51','so',NULL,'also I rejoice now when I behold Thy gentle form. I have drunk the nectar. Now I am alive');
INSERT INTO "vocabulary" VALUES(7763,466,'BG11.52','सुदुर्दर्शम्',NULL,'very hard to see');
INSERT INTO "vocabulary" VALUES(7764,466,'BG11.52','इदम्',NULL,'this');
INSERT INTO "vocabulary" VALUES(7765,466,'BG11.52','रूपम्',NULL,'form');
INSERT INTO "vocabulary" VALUES(7766,466,'BG11.52','दृष्टवानसि',NULL,'thou hast seen');
INSERT INTO "vocabulary" VALUES(7767,466,'BG11.52','यत्',NULL,'which');
INSERT INTO "vocabulary" VALUES(7768,466,'BG11.52','मम',NULL,'My');
INSERT INTO "vocabulary" VALUES(7769,466,'BG11.52','देवाः',NULL,'gods');
INSERT INTO "vocabulary" VALUES(7770,466,'BG11.52','अपि',NULL,'also');
INSERT INTO "vocabulary" VALUES(7771,466,'BG11.52','अस्य',NULL,'(of) this');
INSERT INTO "vocabulary" VALUES(7772,466,'BG11.52','रूपस्य',NULL,'of form');
INSERT INTO "vocabulary" VALUES(7773,466,'BG11.52','नित्यम्',NULL,'ever');
INSERT INTO "vocabulary" VALUES(7774,466,'BG11.52','दर्शनकाङ्क्षिणः',NULL,'(are) desrious to behold.Commentary Lord Krishna says to Arjuna Though the gods long to behold the Cosmic Form yet they have not seen it as you have done. THey can never behold it.Just as the Chataka (a bird) longs for a drop of rain');
INSERT INTO "vocabulary" VALUES(7775,466,'BG11.52','eagerly',NULL,'turning its eyes towards the clouds');
INSERT INTO "vocabulary" VALUES(7776,466,'BG11.52','so',NULL,'also do gods yearn to behold the Cosmic Form but their wishes have not been gratified even in their dreams. Such is that marvellous vision which thou hast easily seen');
INSERT INTO "vocabulary" VALUES(7777,467,'BG11.53','न',NULL,'not');
INSERT INTO "vocabulary" VALUES(7778,467,'BG11.53','अहम्',NULL,'I');
INSERT INTO "vocabulary" VALUES(7779,467,'BG11.53','वेदैः',NULL,'by the Vedas');
INSERT INTO "vocabulary" VALUES(7780,467,'BG11.53','न',NULL,'not');
INSERT INTO "vocabulary" VALUES(7781,467,'BG11.53','तपसा',NULL,'by austerity');
INSERT INTO "vocabulary" VALUES(7782,467,'BG11.53','न',NULL,'not');
INSERT INTO "vocabulary" VALUES(7783,467,'BG11.53','दानेन',NULL,'by gift');
INSERT INTO "vocabulary" VALUES(7784,467,'BG11.53','न',NULL,'not');
INSERT INTO "vocabulary" VALUES(7785,467,'BG11.53','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(7786,467,'BG11.53','इज्यया',NULL,'by sacrifice');
INSERT INTO "vocabulary" VALUES(7787,467,'BG11.53','शक्यः',NULL,'(am) possible');
INSERT INTO "vocabulary" VALUES(7788,467,'BG11.53','एवंविधः',NULL,'like this');
INSERT INTO "vocabulary" VALUES(7789,467,'BG11.53','द्रष्टुम्',NULL,'to be seen');
INSERT INTO "vocabulary" VALUES(7790,467,'BG11.53','दृष्टवानसि',NULL,'(thou) hast seen');
INSERT INTO "vocabulary" VALUES(7791,467,'BG11.53','माम्',NULL,'Me');
INSERT INTO "vocabulary" VALUES(7792,467,'BG11.53','यथा',NULL,'as.Commentary This Cosmic Form which thou hast seen so easily cannot be obtained either by the study of the Vedas and the six modes of philosophy');
INSERT INTO "vocabulary" VALUES(7793,467,'BG11.53','nor',NULL,'by the practice of manifold austerities (penances)');
INSERT INTO "vocabulary" VALUES(7794,467,'BG11.53','nor',NULL,'by charity');
INSERT INTO "vocabulary" VALUES(7795,467,'BG11.53','nor',NULL,'by sacrifices of various kinds.Arjuna was indeed very fortunate in seeing the Cosmic Form.How can the Lord be seen Listen The heart must be overflowing with true devotion to Him. (Cf.XI.48)');
INSERT INTO "vocabulary" VALUES(7796,468,'BG11.54','भक्त्या',NULL,'by devotion');
INSERT INTO "vocabulary" VALUES(7797,468,'BG11.54','तु',NULL,'indeed');
INSERT INTO "vocabulary" VALUES(7798,468,'BG11.54','अनन्यया',NULL,'singleminded');
INSERT INTO "vocabulary" VALUES(7799,468,'BG11.54','शक्यः',NULL,'(am) possible');
INSERT INTO "vocabulary" VALUES(7800,468,'BG11.54','अहम्',NULL,'I');
INSERT INTO "vocabulary" VALUES(7801,468,'BG11.54','एवंविधः',NULL,'of this form');
INSERT INTO "vocabulary" VALUES(7802,468,'BG11.54','अर्जुन',NULL,'O Arjuna');
INSERT INTO "vocabulary" VALUES(7803,468,'BG11.54','ज्ञातुम्',NULL,'to know');
INSERT INTO "vocabulary" VALUES(7804,468,'BG11.54','दृष्टुम्',NULL,'to see');
INSERT INTO "vocabulary" VALUES(7805,468,'BG11.54','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(7806,468,'BG11.54','तत्त्वेन',NULL,'in reality');
INSERT INTO "vocabulary" VALUES(7807,468,'BG11.54','प्रवेष्टुम्',NULL,'to enter into');
INSERT INTO "vocabulary" VALUES(7808,468,'BG11.54','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(7809,468,'BG11.54','परंतप',NULL,'O Parantapa (O scorcher of the foes).Commentary Devotion is the sole means to the realisation of the Cosmic Form.AnanyaBhakti Singleminded devotion. Onepointed unbroken devotion the devotion which does not seek any other object but the Lord alone. In this type of devotion no object other than the Lord is experienced by any of the senses. Egoism and dualism totally vanish.Of this form refers to the Cosmic Form.By singleminded devotion it is possible not only to know Me as declared in the scriptures but also to realise Me');
INSERT INTO "vocabulary" VALUES(7810,468,'BG11.54','to',NULL,'attain liberation. The devotee realises that the Lord is all this and He alone is the ultimate Reality. When he gets this experience of illumination he gets merged in Him. (Cf.VIII.22X.10)');
INSERT INTO "vocabulary" VALUES(7811,469,'BG11.55','मत्कर्मकृत्',NULL,'does actions for Me');
INSERT INTO "vocabulary" VALUES(7812,469,'BG11.55','मत्परमः',NULL,'looks on Me as the Supreme');
INSERT INTO "vocabulary" VALUES(7813,469,'BG11.55','मद्भक्तः',NULL,'is devoted to Me');
INSERT INTO "vocabulary" VALUES(7814,469,'BG11.55','सङ्गवर्जितः',NULL,'is freed from attachment');
INSERT INTO "vocabulary" VALUES(7815,469,'BG11.55','निर्वैरः',NULL,'without enmity');
INSERT INTO "vocabulary" VALUES(7816,469,'BG11.55','सर्वभूतेषु',NULL,'towards all creatures');
INSERT INTO "vocabulary" VALUES(7817,469,'BG11.55','यः',NULL,'who');
INSERT INTO "vocabulary" VALUES(7818,469,'BG11.55','सः',NULL,'he');
INSERT INTO "vocabulary" VALUES(7819,469,'BG11.55','माम्',NULL,'to Me');
INSERT INTO "vocabulary" VALUES(7820,469,'BG11.55','एति',NULL,'goes');
INSERT INTO "vocabulary" VALUES(7821,469,'BG11.55','पाण्डव',NULL,'O Arjuna.Commentary This is the essence of the whole teaching of the Gita. He who practises this teaching will attain Supreme Bliss and Immortality. This verse contains the summary of the entire philosophy of the Gita.He who performs actions (duties) for the sake of the Lord');
INSERT INTO "vocabulary" VALUES(7822,469,'BG11.55','who',NULL,'consecrates all his actions to Him');
INSERT INTO "vocabulary" VALUES(7823,469,'BG11.55','who',NULL,'serves the Lord with his heart and soul');
INSERT INTO "vocabulary" VALUES(7824,469,'BG11.55','who',NULL,'regards the Lord as his supreme goal');
INSERT INTO "vocabulary" VALUES(7825,469,'BG11.55','who',NULL,'lives for Him alone');
INSERT INTO "vocabulary" VALUES(7826,469,'BG11.55','who',NULL,'works for Him alone');
INSERT INTO "vocabulary" VALUES(7827,469,'BG11.55','who',NULL,'sees the Lord in everything');
INSERT INTO "vocabulary" VALUES(7828,469,'BG11.55','who',NULL,'sees the whole world as the Cosmic Form of the Lord and therefore cherishes no feeling of hatred or enmity towards any creature even when great injury has been done by others to him');
INSERT INTO "vocabulary" VALUES(7829,469,'BG11.55','who',NULL,'has no attachment or love to wealth');
INSERT INTO "vocabulary" VALUES(7830,469,'BG11.55','friends',NULL,'and relatives');
INSERT INTO "vocabulary" VALUES(7831,469,'BG11.55','and',NULL,'who seeks nothing else but the Lord');
INSERT INTO "vocabulary" VALUES(7832,469,'BG11.55','realises',NULL,'Him and enters into His Being. He becomes one with Him.Thus in the Upanishads of the glorious Bhagavad Gita');
INSERT INTO "vocabulary" VALUES(7833,469,'BG11.55','the',NULL,'science of the Eternal');
INSERT INTO "vocabulary" VALUES(7834,469,'BG11.55','the',NULL,'scripture of Yoga');
INSERT INTO "vocabulary" VALUES(7835,469,'BG11.55','the',NULL,'dialogue between Sri Krishna and Arjuna');
INSERT INTO "vocabulary" VALUES(7836,469,'BG11.55','ends',NULL,'the eleventh discourse entitledThe Yoga of the Vision of the Cosmic Form.,');
