INSERT INTO "vocabulary" VALUES(10835,605,'BG17.10','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(10836,605,'BG17.10','यत्',NULL,'which');
INSERT INTO "vocabulary" VALUES(10837,605,'BG17.10','उच्छिष्टम्',NULL,'refuse');
INSERT INTO "vocabulary" VALUES(10838,605,'BG17.10','अपि',NULL,'also');
INSERT INTO "vocabulary" VALUES(10839,605,'BG17.10','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(10840,605,'BG17.10','अमेध्यम्',NULL,'impure');
INSERT INTO "vocabulary" VALUES(10841,605,'BG17.10','भोजनम्',NULL,'food');
INSERT INTO "vocabulary" VALUES(10842,605,'BG17.10','तामसप्रियम्',NULL,'liked by the Tamasic.Commentary Cannabis indica (Ganja)');
INSERT INTO "vocabulary" VALUES(10843,605,'BG17.10','all',NULL,'stale and putrid articles');
INSERT INTO "vocabulary" VALUES(10844,605,'BG17.10','are',NULL,'Tamasic.Yatayamam Stale');
INSERT INTO "vocabulary" VALUES(10845,605,'BG17.10','literally',NULL,'means cooked three hours ago. Yatayamam and Gatarasam mean the same thing.Paryushitam Rotten The cooked food which has been kept overnight.Uchchishtam What is left on the plate after a meal.The man whose taste is of a Tamasic nature will eat food in the afternoon that has been cooked on the previous day. He also likes that which is halfcooked or burnt to a cinder. He and all the members of his family sit together and eat from the same dish or plate');
INSERT INTO "vocabulary" VALUES(10846,605,'BG17.10','food',NULL,'that has been mixed into a mess by his children.The food eaten by Tamasic people is stale');
INSERT INTO "vocabulary" VALUES(10847,605,'BG17.10','without',NULL,'juice');
INSERT INTO "vocabulary" VALUES(10848,605,'BG17.10','unripe',NULL,'or overcooked. They do not relish it');
INSERT INTO "vocabulary" VALUES(10849,605,'BG17.10','till',NULL,'it begins to rot and ferment. They take prohibited foods and drinks. They take liors');
INSERT INTO "vocabulary" VALUES(10850,605,'BG17.10','fermented',NULL,'toddy');
INSERT INTO "vocabulary" VALUES(10851,605,'BG17.10','etc',NULL,'They are horrible people with devilish tendencies');
INSERT INTO "vocabulary" VALUES(10852,606,'BG17.11','अफलाकाङ्क्षिभिः',NULL,'by men desiring no fruit');
INSERT INTO "vocabulary" VALUES(10853,606,'BG17.11','यज्ञः',NULL,'sacrifice');
INSERT INTO "vocabulary" VALUES(10854,606,'BG17.11','विधिदृष्टः',NULL,'as enjoined by the ordinance');
