INSERT INTO "vocabulary" VALUES(11667,641,'BG18.18','त्रिविधः',NULL,'threefold');
INSERT INTO "vocabulary" VALUES(11668,641,'BG18.18','कर्मसंग्रहः',NULL,'the basis of action.Commentary Knowledge');
INSERT INTO "vocabulary" VALUES(11669,641,'BG18.18','the',NULL,'knower and the thing to be known');
INSERT INTO "vocabulary" VALUES(11670,641,'BG18.18','are',NULL,'together the seed of this world. This is known as the Triputi or the traid. It is the conjunction of these three that impels a man to threefold action');
INSERT INTO "vocabulary" VALUES(11671,641,'BG18.18','verbal',NULL,'and physical. This triad is the driving force of all the activities of man. He rejoices at the sight of palatable sweetmeats and delicious fruits but is terrified at the sight of a cobra or tiger. The sight of pleasant or unpleasant objects affects him and he attempts either to possess the agreeable objects or to avoid the disagreeable ones.The Antahkarana (the inner instrument) consists of the mind');
INSERT INTO "vocabulary" VALUES(11672,641,'BG18.18','subconscious',NULL,'mind and egoism. The ear');
INSERT INTO "vocabulary" VALUES(11673,641,'BG18.18','the',NULL,'skin');
INSERT INTO "vocabulary" VALUES(11674,641,'BG18.18','the',NULL,'tongue');
INSERT INTO "vocabulary" VALUES(11675,641,'BG18.18','the',NULL,'nose and the eye are the five organs of knowledge. The individual soul');
INSERT INTO "vocabulary" VALUES(11676,641,'BG18.18','propelled',NULL,'by these five senses');
INSERT INTO "vocabulary" VALUES(11677,641,'BG18.18','is',NULL,'led into activity. He does actions with the help of the five organs of action');
INSERT INTO "vocabulary" VALUES(11678,641,'BG18.18','genitals',NULL,'and anus.Jnanam Any knowledge knowledge in general knowledge of worldly objects');
INSERT INTO "vocabulary" VALUES(11679,641,'BG18.18','etcJneyam',NULL,'The object to be known objects in general.Parijnata The knower');
INSERT INTO "vocabulary" VALUES(11680,641,'BG18.18','the',NULL,'experiencer or the enjoyer');
