INSERT INTO "vocabulary" VALUES(11682,641,'BG18.18','a',NULL,'creature of ignorance.This triad forms the threefold impulse to all action');
INSERT INTO "vocabulary" VALUES(11683,641,'BG18.18','to',NULL,'action in general. The performance of an action in order to get a thing or to avoid an object is possible only when there is the conjunction of the three');
INSERT INTO "vocabulary" VALUES(11684,641,'BG18.18','knowable',NULL,'and knower.Karanam The organ That by which something is done. The actions done by the five causes of action');
INSERT INTO "vocabulary" VALUES(11685,641,'BG18.18','the',NULL,'body');
INSERT INTO "vocabulary" VALUES(11686,641,'BG18.18','which',NULL,'are grouped under the three classes according to their respective seats');
INSERT INTO "vocabulary" VALUES(11687,641,'BG18.18','speech',NULL,'and body');
INSERT INTO "vocabulary" VALUES(11688,641,'BG18.18','are',NULL,'all due to the interplay of the organ');
INSERT INTO "vocabulary" VALUES(11689,641,'BG18.18','etcKarta',NULL,'The agent or the doer he who sets the organs in motion or action and puts on the nature of the limiting adjunct or vehicle in which he acts. All actions inhere in these three (the organ');
