INSERT INTO "vocabulary" VALUES(12136,667,'BG18.44','स्वभावजम्',NULL,'born of nature.Commentary When a man performs his duties rightly according to his caste and order of life his heart is purified and he goes to heaven. Apastambha Dharma Sutra declares');
INSERT INTO "vocabulary" VALUES(12137,667,'BG18.44','Men',NULL,'of severla,castes and orders');
INSERT INTO "vocabulary" VALUES(12138,667,'BG18.44','each',NULL,'devoted to his respective duties');
INSERT INTO "vocabulary" VALUES(12139,667,'BG18.44','reap',NULL,'the fruits of their actions after death');
INSERT INTO "vocabulary" VALUES(12140,667,'BG18.44','and',NULL,'then by the residual Karma attain to births in superior Dharma');
INSERT INTO "vocabulary" VALUES(12141,667,'BG18.44','span',NULL,'of life');
INSERT INTO "vocabulary" VALUES(12142,667,'BG18.44','happiness',NULL,'and intelligence (2');
INSERT INTO "vocabulary" VALUES(12143,667,'BG18.44','3',NULL,'There is a vivid description in the Puranas also of the different results and worlds which men of the four castes and orders obtain by discharging their respective duties');
