INSERT INTO "vocabulary" VALUES(12174,669,'BG18.46','मानवः',NULL,'man.Commentary The performance by a man of his own duty is simply carrying into effect the intention of the Supreme from Whom the whole of the creation emanates. When a man worships Him');
INSERT INTO "vocabulary" VALUES(12175,669,'BG18.46','the',NULL,'Supreme Being');
INSERT INTO "vocabulary" VALUES(12176,669,'BG18.46','with',NULL,'the flowers of his action');
INSERT INTO "vocabulary" VALUES(12177,669,'BG18.46','then',NULL,'He is immensely pleased and being thus gratified by such worship He confers on Him');
INSERT INTO "vocabulary" VALUES(12178,669,'BG18.46','as',NULL,'a boon');
INSERT INTO "vocabulary" VALUES(12179,669,'BG18.46','dispassion',NULL,'and discrimination.Pravritti Evolution or activity it proceeds from the Lord');
INSERT INTO "vocabulary" VALUES(12180,669,'BG18.46','the',NULL,'Antaryamin');
INSERT INTO "vocabulary" VALUES(12181,669,'BG18.46','the',NULL,'Inner Ruler.Bhutanam Beings living creatures.Svakarmana With his own duty each according to his caste as described above.Man attains perfection by worshipping the Lord by performing his own duty');
INSERT INTO "vocabulary" VALUES(12182,669,'BG18.46','he',NULL,'becomes alified for the dawn of Selfknowledge (for Jnana Yoga)');
