INSERT INTO "vocabulary" VALUES(12580,691,'BG18.68','पराम्',NULL,'supreme');
INSERT INTO "vocabulary" VALUES(12581,691,'BG18.68','कृत्वा',NULL,'having done');
INSERT INTO "vocabulary" VALUES(12582,691,'BG18.68','माम्',NULL,'to Me');
INSERT INTO "vocabulary" VALUES(12583,691,'BG18.68','एव',NULL,'even');
INSERT INTO "vocabulary" VALUES(12584,691,'BG18.68','एष्यति',NULL,'shall come');
INSERT INTO "vocabulary" VALUES(12585,691,'BG18.68','असंशयः',NULL,'doubtless.Commentary This supreme secret The teachings of the Gita as taught above in the form of a dialogue between Lord Krishna and Arjuna. Why is it called a supreme secret Because it helps one to attain immortality or freedom from the whell of birth and death.He alone');
INSERT INTO "vocabulary" VALUES(12586,691,'BG18.68','who',NULL,'has devotion');
INSERT INTO "vocabulary" VALUES(12587,691,'BG18.68','is',NULL,'alified to receive the teachings of the Gita.Teach with the faith that he is thus doing service to the Lord');
INSERT INTO "vocabulary" VALUES(12588,691,'BG18.68','the',NULL,'Supreme Teacher.Doubtless may also mean freedom from doubts');
INSERT INTO "vocabulary" VALUES(12589,692,'BG18.69','न',NULL,'not');
INSERT INTO "vocabulary" VALUES(12590,692,'BG18.69','च',NULL,'and');
INSERT INTO "vocabulary" VALUES(12591,692,'BG18.69','तस्मात्',NULL,'than he');
INSERT INTO "vocabulary" VALUES(12592,692,'BG18.69','मनुष्येषु',NULL,'among men');
INSERT INTO "vocabulary" VALUES(12593,692,'BG18.69','कश्चित्',NULL,'any');
INSERT INTO "vocabulary" VALUES(12594,692,'BG18.69','मे',NULL,'of Me');
